import { useEffect, useRef, useState } from 'react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from '@/components/ui/dialog'
import { Checkbox } from '@/components/ui/checkbox'
import { useAuth } from '@/hooks/use-auth'
import {
  carregarNegociacao,
  mensagemNegociacao,
  novaChaveNegociacao,
  numeroDecimal,
  registrarNegociacao,
  type RegistrarNegociacaoPayload,
} from '@/services/negociacaoCotacao'
import { toConfirmarCompraError } from '@/services/cotacaoConfirmacao'

interface TargetRow {
  id: string
  linhaId: string
  sku: string
  fabricante: string
  oferta: number
  alvo: string
  selected: boolean
}
export function CounterProposalModal({
  open,
  onOpenChange,
  cotacoesI,
  potencialItens,
  cotacoesF,
  onSaved,
  onReviewOffer,
}: any) {
  const { user } = useAuth()
  const [rows, setRows] = useState<TargetRow[]>([])
  const [discount, setDiscount] = useState('5')
  const [supplier, setSupplier] = useState('all')
  const [busy, setBusy] = useState(false)
  const running = useRef(false)
  const [error, setError] = useState('')
  const [notice, setNotice] = useState('')
  const [uncertain, setUncertain] = useState(false)
  const pending = useRef<Record<string, RegistrarNegociacaoPayload>>({})
  useEffect(() => {
    if (!open) return
    pending.current = {}
    setError('')
    setNotice('')
    setUncertain(false)
    setRows(
      cotacoesI
        .filter((c: any) => c.preco_ofertado > 0)
        .map((c: any) => {
          const matches = potencialItens.filter((p: any) => p.item_id === c.item_id)
          const cf = cotacoesF.find((f: any) => f.id === c.cotacao_fornecedor_id)
          return {
            id: c.id,
            linhaId: matches.length === 1 ? matches[0].id : '',
            sku: matches[0]?.expand?.item_id?.sku || 'Produto',
            fabricante: cf?.expand?.fornecedor_id?.nome || 'Fabricante',
            oferta: c.preco_ofertado,
            alvo: String(c.preco_contraproposta || c.preco_ofertado),
            selected: matches.length === 1,
          }
        }),
    )
    setSupplier('all')
    // Drafts are initialized only on open, never overwritten by a realtime refresh.
  }, [open])
  const visible = rows.filter((r) => supplier === 'all' || r.fabricante === supplier)
  const simulate = () => {
    const d = numeroDecimal(discount)
    if (!Number.isFinite(d) || d < 0 || d >= 100) {
      setError('Informe um desconto entre 0 e menos de 100%.')
      return
    }
    setError('')
    setRows((prev) =>
      prev.map((r) =>
        visible.some((v) => v.id === r.id) && r.selected
          ? { ...r, alvo: (r.oferta * (1 - d / 100)).toFixed(3) }
          : r,
      ),
    )
  }
  const save = async () => {
    if (running.current) return
    const selected = visible.filter((r) => r.selected)
    if (!selected.length) {
      setError('Selecione pelo menos um item.')
      return
    }
    if (
      selected.some(
        (r) => !r.linhaId || !Number.isFinite(numeroDecimal(r.alvo)) || numeroDecimal(r.alvo) <= 0,
      )
    ) {
      setError('Preencha alvos maiores que zero e escolha linhas sem ambiguidade.')
      return
    }
    running.current = true
    setBusy(true)
    setError('')
    setNotice('')
    const saved: string[] = [],
      failures: string[] = []
    let unknown = false
    for (const row of selected) {
      try {
        if (!pending.current[row.id]) {
          const c = await carregarNegociacao(row.id, row.linhaId)
          pending.current[row.id] = {
            cotacao_iten_id: c.oferta.id,
            potencial_iten_id: c.linha.id,
            versao: c.oferta.updated,
            versao_cotacao: c.cotacao.updated,
            versao_item: c.linha.updated,
            tipo: 'contraproposta_c2',
            moeda: c.resposta?.moeda || c.cotacao.oferta_moeda || c.linha.moeda_compra,
            preco: numeroDecimal(row.alvo),
            idempotency_key: novaChaveNegociacao(),
          }
        }
        await registrarNegociacao(pending.current[row.id])
        delete pending.current[row.id]
        saved.push(row.id)
      } catch (e) {
        const err = toConfirmarCompraError(e)
        if ((err.status >= 400 && err.status < 500) || err.code === 'confirmacao_em_validacao')
          delete pending.current[row.id]
        else unknown = true
        failures.push(row.sku + ': ' + mensagemNegociacao(e))
      }
    }
    setRows((prev) => prev.map((r) => (saved.includes(r.id) ? { ...r, selected: false } : r)))
    setUncertain(unknown)
    if (saved.length) {
      setNotice(`${saved.length} alvo(s) salvo(s). Nenhuma compra foi confirmada.`)
      await onSaved?.()
    }
    if (failures.length) setError(failures.join('\n'))
    running.current = false
    setBusy(false)
  }
  return (
    <Dialog
      open={open}
      onOpenChange={(v) => {
        if (!busy && !uncertain) onOpenChange(v)
      }}
    >
      <DialogContent className="max-w-4xl max-h-[90vh]">
        <DialogHeader>
          <DialogTitle>Preparar contraproposta</DialogTitle>
          <DialogDescription>
            Defina os preços alvo da C2. Depois de receber a resposta do fabricante, registre-a e
            revise a compra.
          </DialogDescription>
        </DialogHeader>
        {error && (
          <p
            role="alert"
            className="whitespace-pre-line rounded border border-red-300 bg-red-50 p-3 text-sm text-red-800"
          >
            {error}
          </p>
        )}
        {notice && (
          <p role="status" className="text-sm text-green-800">
            {notice}
          </p>
        )}
        <div className="flex flex-wrap items-end gap-3">
          <div>
            <Label htmlFor="fabricante-alvo">Fabricante</Label>
            <select
              id="fabricante-alvo"
              className="block h-10 rounded border bg-background px-3"
              value={supplier}
              disabled={busy || uncertain}
              onChange={(e) => setSupplier(e.target.value)}
            >
              <option value="all">Todos</option>
              {Array.from(new Set(rows.map((r) => r.fabricante))).map((n) => (
                <option key={n}>{n}</option>
              ))}
            </select>
          </div>
          <div>
            <Label htmlFor="desconto-alvo">Desconto sobre a oferta (%)</Label>
            <Input
              id="desconto-alvo"
              className="w-32"
              inputMode="decimal"
              value={discount}
              disabled={busy || uncertain}
              onChange={(e) => setDiscount(e.target.value)}
            />
          </div>
          <Button variant="secondary" disabled={busy || uncertain} onClick={simulate}>
            Simular nos selecionados
          </Button>
        </div>
        <div className="overflow-auto max-h-[45vh] rounded border">
          <table className="w-full text-sm">
            <thead className="sticky top-0 bg-muted">
              <tr>
                <th className="p-3">
                  <Checkbox
                    aria-label="Selecionar todos os alvos visíveis"
                    disabled={busy || uncertain}
                    checked={visible.length > 0 && visible.every((r) => r.selected)}
                    onCheckedChange={(v) =>
                      setRows((prev) =>
                        prev.map((r) =>
                          visible.some((x) => x.id === r.id) && r.linhaId
                            ? { ...r, selected: v === true }
                            : r,
                        ),
                      )
                    }
                  />
                </th>
                <th className="text-left p-3">SKU / fabricante</th>
                <th className="p-3 text-right">Oferta atual</th>
                <th className="p-3 text-right">Alvo C2</th>
                <th className="p-3">Resposta</th>
              </tr>
            </thead>
            <tbody>
              {visible.map((row) => (
                <tr key={row.id} className="border-t">
                  <td className="p-3">
                    <Checkbox
                      aria-label={'Selecionar ' + row.sku}
                      disabled={busy || uncertain || !row.linhaId}
                      checked={row.selected}
                      onCheckedChange={(v) =>
                        setRows((prev) =>
                          prev.map((r) => (r.id === row.id ? { ...r, selected: v === true } : r)),
                        )
                      }
                    />
                  </td>
                  <td className="p-3">
                    <strong>{row.sku}</strong>
                    <div className="text-xs text-muted-foreground">{row.fabricante}</div>
                    {!row.linhaId && (
                      <p className="text-xs text-red-700">Revise pela linha do potencial.</p>
                    )}
                  </td>
                  <td className="p-3 text-right font-mono">{row.oferta.toFixed(3)}</td>
                  <td className="p-3">
                    <Input
                      aria-label={'Alvo ' + row.sku}
                      className="w-28 text-right"
                      inputMode="decimal"
                      value={row.alvo}
                      disabled={busy || uncertain}
                      onChange={(e) =>
                        setRows((prev) =>
                          prev.map((r) => (r.id === row.id ? { ...r, alvo: e.target.value } : r)),
                        )
                      }
                    />
                  </td>
                  <td className="p-3">
                    <Button
                      variant="outline"
                      size="sm"
                      disabled={busy || uncertain || !row.linhaId}
                      onClick={() => onReviewOffer?.(row.id)}
                    >
                      Registrar / revisar
                    </Button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          {!visible.length && (
            <p className="p-4 text-muted-foreground">
              Preencha e salve as ofertas dos fabricantes para preparar os alvos.
            </p>
          )}
        </div>
        <p className="text-xs text-muted-foreground">
          Cada alvo é salvo com histórico próprio. Se algum item falhar, os itens concluídos
          aparecem desmarcados e os demais continuam selecionados.
        </p>
        <div className="flex justify-end gap-2">
          <Button
            variant="outline"
            disabled={busy || uncertain}
            onClick={() => onOpenChange(false)}
          >
            Fechar
          </Button>
          <Button disabled={busy || !user?.pode_confirmar_compra} onClick={save}>
            {busy
              ? 'Salvando…'
              : uncertain
                ? 'Tentar salvar novamente'
                : 'Salvar alvos selecionados'}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  )
}

import { Input } from '@/components/ui/input'
import { cn } from '@/lib/utils'
import { PriceInput } from '@/components/PriceInput'

export function PriceCell({
  cotacaoF,
  item,
  cotacaoI,
  draftPrice,
  draftMoq,
  isLowest,
  onDraftChange,
  onDraftMoqChange,
  onBlur,
  onToggleWinner,
}: any) {
  const currentPrice = draftPrice !== undefined ? draftPrice : cotacaoI?.preco_ofertado || 0
  const currentMoq = draftMoq !== undefined ? draftMoq : cotacaoI?.quantidade_minima || 0

  const hasCounter = cotacaoI && cotacaoI.preco_contraproposta > 0
  const counterPrice = cotacaoI?.preco_contraproposta

  return (
    <div
      title="Revisar resposta e confirmar compra"
      onClick={() => onToggleWinner(cotacaoF.id, item.item_id, cotacaoI?.id, cotacaoI?.vencedor, item.id)}
      className={cn(
        'p-1.5 rounded-md flex flex-col gap-1.5 relative group min-h-[44px] cursor-pointer transition-all',
        cotacaoI?.vencedor
          ? 'bg-blue-100 hover:bg-blue-100/90'
          : isLowest
            ? 'bg-emerald-100/70 ring-1.5 ring-emerald-500/80 hover:bg-emerald-100'
            : 'hover:bg-muted/50',
      )}
    >
      <div className="flex items-center gap-1">
        <div onClick={(e) => e.stopPropagation()} className="flex-1 min-w-0">
          <PriceInput
            disabled={!!cotacaoI?.vencedor}
            value={currentPrice || undefined}
            onChange={(val) => onDraftChange(cotacaoF.id, item.item_id, val || 0)}
            onBlur={() => {
              if (onBlur && (draftPrice !== undefined || draftMoq !== undefined)) {
                onBlur(cotacaoF.id, item.item_id, currentPrice, currentMoq, cotacaoI?.id)
              }
            }}
            className={cn(
              'h-7 text-xs text-right font-mono w-full font-semibold transition-colors',
              cotacaoI?.vencedor
                ? 'bg-white text-blue-900 border-border font-bold focus-visible:ring-blue-400 shadow-2xs'
                : isLowest
                  ? 'bg-white/90 text-emerald-800 font-bold border-emerald-400 focus-visible:ring-emerald-400 shadow-2xs'
                  : 'bg-background text-foreground',
            )}
          />
        </div>
        {hasCounter && (
          <span
            className={cn(
              'font-mono text-[10px] font-bold whitespace-nowrap pl-1',
              cotacaoI?.vencedor ? 'text-amber-700' : 'text-amber-600',
            )}
            title="Contraproposta"
          >
            $ {counterPrice.toFixed(3)}
          </span>
        )}
      </div>

      <button type="button" className="text-xs text-blue-700 underline text-left" onClick={e=>{e.stopPropagation();onToggleWinner(cotacaoF.id,item.item_id,cotacaoI?.id,cotacaoI?.vencedor,item.id)}}>Revisar compra {item.expand?.item_id?.sku||''}</button>
      {currentMoq > 0 || (draftMoq !== undefined && draftMoq !== 0) ? (
        <div className="flex items-center gap-2">
          <span
            className={cn(
              'text-[9px] uppercase font-bold w-6 shrink-0',
              cotacaoI?.vencedor ? 'text-blue-700' : 'text-muted-foreground',
            )}
          >
            MOQ
          </span>
          <Input
            type="text"
            inputMode="numeric"
            value={currentMoq || ''}
            onChange={(e) => {
              const val = e.target.value.replace(/[^0-9]/g, '')
              onDraftMoqChange(cotacaoF.id, item.item_id, val ? parseInt(val, 10) : 0)
            }}
            onBlur={() => {
              if (onBlur && (draftPrice !== undefined || draftMoq !== undefined)) {
                onBlur(cotacaoF.id, item.item_id, currentPrice, currentMoq, cotacaoI?.id)
              }
            }}
            onClick={(e) => e.stopPropagation()}
            className={cn(
              'h-6 text-[10px] text-right font-mono flex-1 min-w-0',
              cotacaoI?.vencedor
                ? 'bg-white text-blue-900 border-border focus-visible:ring-blue-400'
                : isLowest
                  ? 'bg-white/90 border-emerald-300 text-emerald-900 focus-visible:ring-emerald-400'
                  : '',
            )}
            disabled={!!cotacaoI?.vencedor}
            placeholder="MOQ"
          />
        </div>
      ) : (
        <div className="hidden group-hover:flex justify-end">
          <button
            className={cn(
              'text-[9px] underline pr-1',
              cotacaoI?.vencedor
                ? 'text-blue-600 hover:text-blue-800'
                : 'text-muted-foreground hover:text-foreground',
            )}
            onClick={(e) => {
              e.stopPropagation()
              onDraftMoqChange(cotacaoF.id, item.item_id, 1)
            }}
          >
            + MOQ
          </button>
        </div>
      )}
    </div>
  )
}

import { useEffect, useRef, useState } from 'react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Checkbox } from '@/components/ui/checkbox'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from '@/components/ui/dialog'
import { Badge } from '@/components/ui/badge'
import { useAuth } from '@/hooks/use-auth'
import { computeVenda } from '@/lib/money'
import {
  confirmarCompra,
  salvarMargemNegociada,
  toConfirmarCompraError,
  type ConfirmarCompraPayload,
} from '@/services/cotacaoConfirmacao'
import {
  carregarNegociacao,
  mensagemNegociacao,
  novaChaveNegociacao,
  numeroDecimal,
  payloadConfirmacao,
  registrarNegociacao,
  validadeResposta,
  type NegociacaoContexto,
  type RegistrarNegociacaoPayload,
} from '@/services/negociacaoCotacao'

export interface RevisaoItem {
  ofertaId: string
  linhaId: string
  titulo: string
}
export function PurchaseReviewDialog({
  items,
  onClose,
  onConfirmed,
}: {
  items: RevisaoItem[]
  onClose: () => void
  onConfirmed: () => void
}) {
  const [index, setIndex] = useState(0)
  const [busy, setBusy] = useState(false)
  return (
    <Dialog
      open={items.length > 0}
      onOpenChange={(open) => {
        if (!open && !busy) onClose()
      }}
    >
      <DialogContent
        className="max-w-3xl max-h-[90vh]"
        onInteractOutside={(e) => {
          if (busy) e.preventDefault()
        }}
        onEscapeKeyDown={(e) => {
          if (busy) e.preventDefault()
        }}
      >
        <DialogHeader>
          <DialogTitle>Revisar compra</DialogTitle>
          <DialogDescription>
            Confira a resposta do fabricante, a margem e os valores antes de confirmar cada item.
          </DialogDescription>
        </DialogHeader>
        {items.length > 1 && (
          <div className="flex flex-wrap gap-2" aria-label="Itens para revisar">
            {items.map((x, i) => (
              <Button
                key={x.ofertaId + ':' + x.linhaId}
                size="sm"
                variant={i === index ? 'default' : 'outline'}
                disabled={busy}
                onClick={() => setIndex(i)}
              >
                {i + 1}. {x.titulo}
              </Button>
            ))}
          </div>
        )}
        {items[index] && (
          <ReviewItem
            key={items[index].ofertaId + ':' + items[index].linhaId}
            item={items[index]}
            onBusy={setBusy}
            onConfirmed={onConfirmed}
          />
        )}
        <div className="flex justify-end">
          <Button variant="outline" disabled={busy} onClick={onClose}>
            Fechar revisão
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  )
}
function ReviewItem({
  item,
  onBusy,
  onConfirmed,
}: {
  item: RevisaoItem
  onBusy: (b: boolean) => void
  onConfirmed: () => void
}) {
  const { user } = useAuth()
  const [context, setContext] = useState<NegociacaoContexto | null>(null)
  const [step, setStep] = useState(0)
  const [busy, setBusy] = useState(false)
  const running = useRef(false)
  const [error, setError] = useState('')
  const [notice, setNotice] = useState('')
  const [margin, setMargin] = useState('')
  const [precision, setPrecision] = useState<2 | 3>(2)
  const [adjust, setAdjust] = useState(false)
  const [reviewed, setReviewed] = useState(false)
  const [receipt, setReceipt] = useState<any>(null)
  const [response, setResponse] = useState({
    preco: '',
    moq: '0',
    moeda: '',
    validade: '',
    referencia: '',
    incoterm: '',
    pagamento: '',
    fabricacao: '',
  })
  const [attested, setAttested] = useState(false)
  const pendingConfirm = useRef<ConfirmarCompraPayload | null>(null)
  const pendingResponse = useRef<RegistrarNegociacaoPayload | null>(null)
  const [uncertain, setUncertain] = useState(false)
  useEffect(() => {
    onBusy(busy || uncertain)
  }, [busy, uncertain, onBusy])
  const authorized = user?.pode_confirmar_compra === true
  const load = async () => {
    const c = await carregarNegociacao(item.ofertaId, item.linhaId)
    setContext(c)
    setMargin(c.oferta.margem_versao >= 1 ? String(c.oferta.margem_negociada) : '')
    setPrecision(c.oferta.precisao_negociada === 3 ? 3 : 2)
    setResponse({
      preco: String(c.oferta.preco_ofertado || ''),
      moq: String(c.oferta.quantidade_minima || 0),
      moeda: c.resposta?.moeda || c.cotacao.oferta_moeda || '',
      validade: '',
      referencia: '',
      incoterm: c.cotacao.incoterm || '',
      pagamento: c.cotacao.condicao_pagamento || '',
      fabricacao: c.cotacao.tempo_fabricacao || '',
    })
    setReviewed(false)
    setAdjust(false)
    return c
  }
  useEffect(() => {
    let active = true
    carregarNegociacao(item.ofertaId, item.linhaId)
      .then((c) => {
        if (!active) return
        setContext(c)
        setStep(c.resposta ? 1 : 0)
        setMargin(c.oferta.margem_versao >= 1 ? String(c.oferta.margem_negociada) : '')
        setPrecision(c.oferta.precisao_negociada === 3 ? 3 : 2)
        setResponse({
          preco: String(c.oferta.preco_ofertado || ''),
          moq: String(c.oferta.quantidade_minima || 0),
          moeda: c.resposta?.moeda || c.cotacao.oferta_moeda || '',
          validade: '',
          referencia: '',
          incoterm: c.cotacao.incoterm || '',
          pagamento: c.cotacao.condicao_pagamento || '',
          fabricacao: c.cotacao.tempo_fabricacao || '',
        })
      })
      .catch((e) => {
        if (active) setError(mensagemNegociacao(e))
      })
    return () => {
      active = false
    }
  }, [item.ofertaId, item.linhaId])
  const run = async (fn: () => Promise<void>) => {
    if (running.current) return
    running.current = true
    setBusy(true)
    setError('')
    setNotice('')
    try {
      await fn()
    } catch (e) {
      setError(mensagemNegociacao(e))
    } finally {
      running.current = false
      setBusy(false)
    }
  }
  const saveResponse = () =>
    run(async () => {
      if (!context) return
      if (!pendingResponse.current) {
        const price = numeroDecimal(response.preco),
          moq = numeroDecimal(response.moq)
        if (
          !attested ||
          !Number.isFinite(price) ||
          price <= 0 ||
          !Number.isFinite(moq) ||
          moq < 0 ||
          !response.referencia.trim() ||
          !validadeResposta(response.validade) ||
          !/^[A-Z]{3}$/.test(response.moeda)
        )
          throw new Error(
            'Preencha preço, MOQ, moeda, validade e referência, e confirme a origem da resposta.',
          )
        pendingResponse.current = {
          cotacao_iten_id: context.oferta.id,
          potencial_iten_id: context.linha.id,
          versao: context.oferta.updated,
          versao_cotacao: context.cotacao.updated,
          versao_item: context.linha.updated,
          tipo: 'resposta_fabricante',
          preco: price,
          moq,
          moeda: response.moeda,
          unidade: context.linha.unidade_medida,
          validade_oferta: validadeResposta(response.validade),
          data_oferta: new Date().toISOString(),
          referencia_resposta: response.referencia,
          incoterm: response.incoterm,
          condicao_pagamento: response.pagamento,
          tempo_fabricacao: response.fabricacao,
          confirmo_resposta_fabricante: true,
          idempotency_key: novaChaveNegociacao(),
        }
      }
      try {
        await registrarNegociacao(pendingResponse.current)
        pendingResponse.current = null
        setUncertain(false)
        await load()
        setStep(1)
        setNotice('Resposta registrada. Confira agora a margem de venda.')
      } catch (e) {
        const err = toConfirmarCompraError(e)
        if ((err.status >= 400 && err.status < 500) || err.code === 'confirmacao_em_validacao') {
          pendingResponse.current = null
          setUncertain(false)
        } else setUncertain(true)
        throw e
      }
    })
  const saveMargin = () =>
    run(async () => {
      if (!context) return
      const m = numeroDecimal(margin)
      if (!Number.isFinite(m) || m < 0 || m >= 100)
        throw new Error('Informe uma margem entre 0 e menos de 100%.')
      try {
        await salvarMargemNegociada({
          cotacao_iten_id: context.oferta.id,
          versao: context.oferta.updated,
          margem_versao_esperada: context.oferta.margem_versao || 0,
          margem_negociada: m,
          precisao_negociada: precision,
        })
        await load()
        setStep(2)
      } catch (e) {
        const original = e
        await load().catch(() => {})
        throw original
      }
    })
  const confirm = () =>
    run(async () => {
      if (!context || !context.resposta) return
      if (!pendingConfirm.current) pendingConfirm.current = payloadConfirmacao(context, adjust)
      try {
        const result = await confirmarCompra(pendingConfirm.current)
        pendingConfirm.current = null
        setUncertain(false)
        setReceipt(result.recibo)
        await load().catch(() => {})
        onConfirmed()
      } catch (e) {
        const err = toConfirmarCompraError(e)
        if ((err.status >= 400 && err.status < 500) || err.code === 'confirmacao_em_validacao') {
          pendingConfirm.current = null
          setUncertain(false)
        } else setUncertain(true)
        throw e
      }
    })
  const money = (n: number, currency = context?.resposta?.moeda || response.moeda) =>
    Number.isFinite(n)
      ? `${currency} ${n.toLocaleString('pt-BR', { minimumFractionDigits: precision, maximumFractionDigits: precision })}`
      : '—'
  if (!context) return <div role="status">{error || 'Carregando dados da cotação…'}</div>
  const evidence = context.resposta
  const amount = evidence?.preco || 0
  const marginNumber = numeroDecimal(margin)
  const sale = computeVenda(amount, marginNumber)
  const rounded = sale !== undefined ? Number(sale.toFixed(precision)) : NaN
  const quantity = adjust
    ? Math.max(context.linha.quantidade, evidence?.moq || 0)
    : context.linha.quantidade
  const needsMoq = !!evidence && context.linha.quantidade < evidence.moq
  const termsValid = !!evidence && Date.parse(evidence.validade_oferta) >= Date.now()
  const marginSaved =
    context.oferta.margem_versao >= 1 &&
    Number(context.oferta.margem_negociada) === marginNumber &&
    context.oferta.precisao_negociada === precision
  const canConfirm =
    authorized &&
    termsValid &&
    marginSaved &&
    (!needsMoq || adjust) &&
    reviewed &&
    !context.confirmada &&
    !receipt
  const field = (key: keyof typeof response, label: string, type = 'text') => (
    <div className="space-y-1">
      <Label htmlFor={'resposta-' + key}>{label}</Label>
      <Input
        id={'resposta-' + key}
        type={type}
        disabled={busy || uncertain || !authorized}
        value={response[key]}
        onChange={(e) =>
          setResponse({
            ...response,
            [key]: key === 'moeda' ? e.target.value.toUpperCase() : e.target.value,
          })
        }
      />
    </div>
  )
  return (
    <div className="space-y-4" aria-busy={busy}>
      <div>
        <p className="font-semibold">
          {context.produto.sku} · {context.fabricante.nome}
        </p>
        <p className="text-sm text-muted-foreground">
          Quantidade solicitada: {context.linha.quantidade} {context.linha.unidade_medida}
          {context.oferta.preco_contraproposta > 0
            ? ` · Alvo C2: ${money(context.oferta.preco_contraproposta)}`
            : ''}
        </p>
      </div>
      {!authorized && (
        <p role="alert" className="rounded border p-3 text-sm">
          Sua conta ainda não está habilitada para confirmar compras. Atualize sua sessão após a
          liberação da equipe.
        </p>
      )}
      {error && (
        <p
          role="alert"
          className="rounded border border-red-300 bg-red-50 p-3 text-sm text-red-800"
        >
          {error}
        </p>
      )}
      {notice && (
        <p role="status" className="text-sm text-green-800">
          {notice}
        </p>
      )}
      {receipt ? (
        <div className="rounded-lg border border-green-300 bg-green-50 p-4" role="status">
          <h3 className="font-semibold text-green-900">Compra confirmada</h3>
          <p>
            {money(receipt.preco_compra)} de compra · {money(receipt.preco_unitario)} de venda ·{' '}
            {receipt.quantidade} {receipt.unidade}
          </p>
          <p className="text-xs mt-2">
            Registro: {receipt.rodada.id} ·{' '}
            {new Date(receipt.data_confirmacao).toLocaleString('pt-BR')}
          </p>
        </div>
      ) : (
        <>
          {context.confirmada && (
            <p className="rounded bg-green-50 p-3 text-green-900" role="status">
              Esta resposta já foi confirmada. Para uma nova negociação, registre uma nova resposta
              recebida do fabricante.
            </p>
          )}
          <nav className="flex flex-wrap gap-2" aria-label="Etapas da compra">
            {['1. Resposta do fabricante', '2. Margem e venda', '3. Conferência'].map((name, i) => (
              <Button
                key={name}
                size="sm"
                variant={step === i ? 'default' : 'outline'}
                disabled={busy || uncertain || (i > 0 && !evidence)}
                onClick={() => setStep(i)}
              >
                {name}
              </Button>
            ))}
          </nav>
          {step === 0 && (
            <section className="space-y-3" aria-label="Registro da resposta">
              <p className="text-sm text-muted-foreground">
                Registre o que o fabricante respondeu. O alvo da C2 não preenche este registro e a
                compra só muda após a confirmação final.
              </p>
              <div className="grid grid-cols-2 gap-3">
                {field('preco', 'Preço recebido')}
                {field('moeda', 'Moeda (USD, CNY, EUR…)')}
                {field('moq', 'Quantidade mínima (MOQ)')}
                {field('validade', 'Válida até (DD/MM/AAAA)')}
                {field('incoterm', 'Incoterm')}
                {field('pagamento', 'Condição de pagamento')}
                {field('fabricacao', 'Tempo de fabricação')}
                {field('referencia', 'Referência da resposta (e-mail, data ou observação)')}
              </div>
              <p className="text-sm">
                Unidade: {context.linha.unidade_medida}. A moeda não é convertida automaticamente.
              </p>
              <label className="flex gap-2 text-sm items-start">
                <Checkbox
                  aria-label="Confirmo a origem da resposta"
                  checked={attested}
                  disabled={busy || uncertain || !authorized}
                  onCheckedChange={(v) => setAttested(v === true)}
                />
                Confirmo que estes dados correspondem à resposta recebida do fabricante.
              </label>
              <Button disabled={busy || !authorized} onClick={saveResponse}>
                {busy
                  ? 'Registrando…'
                  : pendingResponse.current
                    ? 'Tentar registrar novamente'
                    : 'Registrar resposta e continuar'}
              </Button>
            </section>
          )}
          {step === 1 && evidence && (
            <section className="space-y-3" aria-label="Margem e venda">
              <div className="rounded bg-muted p-3 text-sm">
                Resposta recebida: <strong>{money(evidence.preco, evidence.moeda)}</strong> por{' '}
                {evidence.unidade}. Válida até{' '}
                {new Date(evidence.validade_oferta).toLocaleDateString('pt-BR')}.
                <p>{evidence.observacoes}</p>
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div className="space-y-1">
                  <Label htmlFor="margem-venda">Margem sobre a venda (%)</Label>
                  <Input
                    id="margem-venda"
                    inputMode="decimal"
                    value={margin}
                    disabled={busy || !authorized}
                    onChange={(e) => {
                      setMargin(e.target.value)
                      setReviewed(false)
                    }}
                  />
                </div>
                <div className="space-y-1">
                  <Label htmlFor="precisao-venda">Casas decimais do preço</Label>
                  <select
                    id="precisao-venda"
                    className="flex h-10 w-full rounded-md border bg-background px-3"
                    value={precision}
                    disabled={busy || !authorized}
                    onChange={(e) => {
                      setPrecision(Number(e.target.value) as 2 | 3)
                      setReviewed(false)
                    }}
                  >
                    <option value="2">2 casas</option>
                    <option value="3">3 casas</option>
                  </select>
                </div>
              </div>
              <p>
                Preço de venda calculado: <strong>{money(rounded, evidence.moeda)}</strong>
              </p>
              <p className="text-xs text-muted-foreground">
                Venda = compra ÷ (1 − margem/100). Nenhuma margem padrão é aplicada sem sua escolha.
              </p>
              <Button disabled={busy || !authorized || !termsValid} onClick={saveMargin}>
                {busy ? 'Salvando…' : 'Salvar margem e conferir'}
              </Button>
              {!termsValid && (
                <p role="alert" className="text-sm text-red-700">
                  A resposta venceu. Registre uma nova resposta antes de continuar.
                </p>
              )}
            </section>
          )}
          {step === 2 && evidence && (
            <section className="space-y-3" aria-label="Conferência final">
              <dl className="grid grid-cols-2 gap-3 rounded-lg border p-4 text-sm">
                <div>
                  <dt>Compra unitária</dt>
                  <dd className="font-semibold">{money(amount, evidence.moeda)}</dd>
                </div>
                <div>
                  <dt>Venda unitária</dt>
                  <dd className="font-semibold">{money(rounded, evidence.moeda)}</dd>
                </div>
                <div>
                  <dt>Quantidade</dt>
                  <dd>
                    {quantity} {evidence.unidade}
                  </dd>
                </div>
                <div>
                  <dt>Margem sobre venda</dt>
                  <dd>{margin}%</dd>
                </div>
                <div>
                  <dt>Total de compra</dt>
                  <dd>{money(amount * quantity, evidence.moeda)}</dd>
                </div>
                <div>
                  <dt>Total de venda</dt>
                  <dd>{money(rounded * quantity, evidence.moeda)}</dd>
                </div>
              </dl>
              <p className="text-sm">
                {evidence.incoterm || 'Incoterm não informado'} ·{' '}
                {evidence.condicao_pagamento || 'Pagamento não informado'} ·{' '}
                {evidence.tempo_fabricacao || 'Prazo não informado'}
              </p>
              {needsMoq && (
                <label className="flex items-start gap-2 rounded border border-amber-300 p-3 text-sm">
                  <Checkbox
                    aria-label="Ajustar quantidade ao MOQ"
                    disabled={busy || uncertain}
                    checked={adjust}
                    onCheckedChange={(v) => {
                      setAdjust(v === true)
                      setReviewed(false)
                    }}
                  />
                  A quantidade solicitada é {context.linha.quantidade}. Autorizo ajustar para o
                  mínimo de {evidence.moq} {evidence.unidade}.
                </label>
              )}
              {!marginSaved && (
                <p role="alert" className="text-sm text-amber-800">
                  Salve a margem e a precisão antes de confirmar.
                </p>
              )}
              <label className="flex items-start gap-2 text-sm">
                <Checkbox
                  aria-label="Conferi os dados da compra"
                  checked={reviewed}
                  disabled={busy || uncertain || !authorized}
                  onCheckedChange={(v) => setReviewed(v === true)}
                />
                Conferi fabricante, resposta, moeda, unidade, quantidade, margem e condições.
              </label>
              <Button disabled={busy || (!canConfirm && !pendingConfirm.current)} onClick={confirm}>
                {busy
                  ? 'Confirmando…'
                  : pendingConfirm.current
                    ? 'Tentar confirmar novamente'
                    : 'Confirmar compra deste item'}
              </Button>
            </section>
          )}
          <Button
            variant="outline"
            size="sm"
            disabled={busy || uncertain}
            onClick={() =>
              run(async () => {
                await load()
                setNotice('Dados atualizados. Confira novamente antes de confirmar.')
              })
            }
          >
            Atualizar dados
          </Button>
        </>
      )}
      <details className="rounded border p-3">
        <summary className="cursor-pointer text-sm font-medium">
          Histórico de negociação ({context.rodadas.length})
        </summary>
        <ol className="mt-3 space-y-3 text-sm">
          {context.rodadas.map((r) => (
            <li key={r.id} className="border-t pt-2">
              <Badge variant="outline">
                {{
                  contraproposta_c2: 'Alvo C2',
                  resposta_fabricante: 'Resposta do fabricante',
                  selecao: 'Compra confirmada',
                  oferta_original: 'Oferta original',
                  oferta_confirmada: 'Oferta confirmada',
                }[r.tipo] || r.tipo}
              </Badge>
              <span className="ml-2">
                {money(r.preco, r.moeda)} · {new Date(r.created).toLocaleString('pt-BR')}
              </span>
              <p className="text-xs text-muted-foreground mt-1">
                {r.observacoes} · Responsável: {r.autor}
              </p>
            </li>
          ))}
        </ol>
        {!context.rodadas.length && (
          <p className="mt-2 text-sm text-muted-foreground">Nenhum registro ainda.</p>
        )}
      </details>
    </div>
  )
}

