interface QuotationMatrixProps {
  onAccepted?: () => void
}

export default function QuotationMatrix({ onAccepted }: QuotationMatrixProps = {}) {
  const [searchParams] = useSearchParams()
  const potencialId =
    searchParams.get('id') || searchParams.get('potencialId') || searchParams.get('potencial_id')
  const { toast } = useToast()

  const [potencialItens, setPotencialItens] = useState<any[]>([])
  const [cotacoesF, setCotacoesF] = useState<any[]>([])
  const [cotacoesI, setCotacoesI] = useState<any[]>([])
  const [fornecedores, setFornecedores] = useState<any[]>([])
  const [latestHistorico, setLatestHistorico] = useState<Record<string, any>>({})
  const [potencial, setPotencial] = useState<any>(null)

  const [isAddOpen, setIsAddOpen] = useState(false)
  const [isCounterOpen, setIsCounterOpen] = useState(false)
  const [isCompact, setIsCompact] = useState(false)
  const [comboboxSearch, setComboboxSearch] = useState('')

  const [draftPrices, setDraftPrices] = useState<Record<string, number>>({})
  const [draftMoqs, setDraftMoqs] = useState<Record<string, number>>({})
  const [cfDrafts, setCfDrafts] = useState<
    Record<string, { incoterm?: string; tempo_fabricacao?: string; condicao_pagamento?: string }>
  >({})
  const [savingCfIds, setSavingCfIds] = useState<Record<string, boolean>>({})
  const [isSavingDraft, setIsSavingDraft] = useState(false)

  const [suppliersWithHistory, setSuppliersWithHistory] = useState<Set<string>>(new Set())
  const [prioritizedSuppliers, setPrioritizedSuppliers] = useState<Set<string>>(new Set())

  const [reviewItems, setReviewItems] = useState<RevisaoItem[]>([])

  const [importState, setImportState] = useState<{
    cfId: string
    file: File
    rows: string[][]
    headers: string[]
    open: boolean
  } | null>(null)

  const [searchTerm, setSearchTerm] = useState('')
  const [filterByLine, setFilterByLine] = useState(false)

  const loadData = async () => {
    if (!potencialId) return
    try {
      const [pItens, cF, cI, forn] = await Promise.all([
        pb.collection('potencial_itens').getFullList({
          filter: `potencial_id="${potencialId}"`,
          expand: 'item_id,item_id.linha_id,item_id.acabamento_id',
          sort: 'ordem',
        }),
        pb.collection('cotacoes_fornecedor').getFullList({
          filter: `potencial_id="${potencialId}"`,
          expand: 'fornecedor_id',
          sort: 'created',
        }),
        pb.collection('cotacoes_itens').getFullList({
          filter: `cotacao_fornecedor_id.potencial_id="${potencialId}"`,
          expand: 'cotacao_fornecedor_id,cotacao_fornecedor_id.fornecedor_id',
        }),
        pb.collection('fornecedores').getFullList({ filter: 'ativo=true', sort: 'nome' }),
      ])
      setPotencialItens(pItens)
      setCotacoesF(cF)
      setCotacoesI(cI)
      setFornecedores(forn)

      const linhaIds = Array.from(
        new Set(pItens.map((i) => i.expand?.item_id?.linha_id).filter(Boolean)),
      )
      if (linhaIds.length > 0) {
        const histLinhas = await pb.collection('historico_precos').getFullList({
          filter: `(${linhaIds.map((id) => `item_id.linha_id="${id}"`).join(' || ')}) && tipo="compra"`,
          fields: 'fornecedor',
        })
        setPrioritizedSuppliers(new Set(histLinhas.map((h) => h.fornecedor)))
      }

      const allHist = await pb
        .collection('historico_precos')
        .getList(1, 1000, { filter: 'tipo="compra"', fields: 'fornecedor' })
      const allNotas = await pb
        .collection('potencial_notas')
        .getList(1, 1000, { filter: 'fornecedor_id != ""', fields: 'fornecedor_id' })

      const histSet = new Set<string>()
      allHist.items.forEach((h) => histSet.add(h.fornecedor))
      allNotas.items.forEach((n) => histSet.add(n.fornecedor_id))
      setSuppliersWithHistory(histSet)

      const potencialRecord = await pb.collection('potenciais').getOne(potencialId)
      setPotencial(potencialRecord)
      const potencialDate = potencialRecord.created

      const itemIds = Array.from(new Set(pItens.map((i) => i.item_id)))
      const latestHist: Record<string, any> = {}
      if (itemIds.length > 0) {
        const chunkSize = 50
        for (let i = 0; i < itemIds.length; i += chunkSize) {
          const chunk = itemIds.slice(i, i + chunkSize)
          const itemFilter = chunk.map((id) => `item_id="${id}"`).join(' || ')
          const h = await pb.collection('historico_precos').getFullList({
            filter: `(${itemFilter}) && tipo="compra" && created < "${potencialDate}"`,
            sort: '-data_cotacao',
          })
          h.forEach((record) => {
            if (!latestHist[record.item_id]) {
              latestHist[record.item_id] = record
            }
          })
        }
      }
      setLatestHistorico(latestHist)
    } catch (err) {
      console.error(err)
    }
  }

  useEffect(() => {
    loadData()
  }, [potencialId])

  useRealtime('potencial_itens', loadData)
  useRealtime('cotacoes_fornecedor', loadData)
  useRealtime('cotacoes_itens', loadData)

  const openReview = (offers:any[], linhaId?:string) => {
    if(Object.keys(draftPrices).length || Object.keys(draftMoqs).length || Object.keys(cfDrafts).length) {
      toast({title:'Salve as edições primeiro',description:'Use Salvar Cotação e abra a revisão novamente.'});return
    }
    const entries:RevisaoItem[]=[]
    for(const offer of offers) {
      const matching=potencialItens.filter(pi=>pi.item_id===offer.item_id&&(!linhaId||pi.id===linhaId))
      if(matching.length!==1){toast({title:'Escolha a linha do potencial',description:'Há mais de uma linha para este produto. Abra a revisão pela célula da linha desejada.',variant:'destructive'});return}
      const pi=matching[0]
      entries.push({ofertaId:offer.id,linhaId:pi.id,titulo:pi.expand?.item_id?.sku||'Item'})
    }
    if(!entries.length){toast({title:'Nenhuma oferta salva',description:'Preencha e salve a oferta do fabricante antes de revisar.'});return}
    setReviewItems(entries)
  }
  const handleSelectAllFor = (cfId:string) => openReview(cotacoesI.filter(c=>c.cotacao_fornecedor_id===cfId))

  const handleFileSelect = (cfId: string, file: File) => {
    const reader = new FileReader()
    reader.onload = (e) => {
      const text = e.target?.result as string
      const rows: string[][] = []
      let row: string[] = []
      let inQuotes = false
      let val = ''
      for (let i = 0; i < text.length; i++) {
        const char = text[i]
        if (char === '"') {
          if (inQuotes && text[i + 1] === '"') {
            val += '"'
            i++
          } else {
            inQuotes = !inQuotes
          }
        } else if ((char === ',' || char === ';') && !inQuotes) {
          row.push(val.trim())
          val = ''
        } else if (char === '\n' && !inQuotes) {
          row.push(val.trim())
          rows.push(row)
          row = []
          val = ''
        } else if (char === '\r' && !inQuotes) {
          // Ignore
        } else {
          val += char
        }
      }
      if (val !== '' || row.length > 0) {
        row.push(val.trim())
        rows.push(row)
      }

      const validRows = rows.filter((r) => r.length > 0 && r.some((c) => c !== ''))
      if (validRows.length > 0) {
        setImportState({ cfId, file, rows: validRows, headers: validRows[0], open: true })
      }
    }
    reader.readAsText(file)
  }

  const handleConfirmImport = async (skuIdx: number, priceIdx: number, moqIdx: number) => {
    if (!importState) return
    const { cfId, rows } = importState
    let updated = 0
    let notFound = 0
    const promises = []

    for (let i = 1; i < rows.length; i++) {
      const row = rows[i]
      const sku = row[skuIdx]
      const priceStr = row[priceIdx]
      if (!sku || !priceStr) continue

      const pi = potencialItens.find((p) => p.expand?.item_id?.sku === sku)
      if (!pi) {
        notFound++
        continue
      }

      const price = parseFloat(priceStr.replace(',', '.'))
      if (isNaN(price)) continue

      let moq = 0
      if (moqIdx >= 0 && row[moqIdx]) {
        moq = parseInt(row[moqIdx], 10) || 0
      }

      const ci = cotacoesI.find((c) => c.cotacao_fornecedor_id === cfId && c.item_id === pi.item_id)
      if (ci) {
        const updateData: any = { preco_ofertado: price }
        if (moqIdx >= 0) updateData.quantidade_minima = moq
        promises.push(pb.collection('cotacoes_itens').update(ci.id, updateData))
      } else {
        promises.push(
          pb.collection('cotacoes_itens').create({
            cotacao_fornecedor_id: cfId,
            item_id: pi.item_id,
            preco_ofertado: price,
            quantidade_minima: moq,
            vencedor: false,
          }),
        )
      }
      updated++
    }
    await Promise.all(promises)
    toast({
      title: `Importação concluída`,
      description: `${updated} preços atualizados. ${notFound} SKUs não encontrados.`,
    })
    setImportState(null)
  }

  const handleSaveSupplierOptions = async (cfId: string) => {
    const draft = cfDrafts[cfId]
    if (!draft || Object.keys(draft).length === 0) {
      toast({
        title: 'Nenhuma alteração',
        description: 'Não há alterações pendentes nas opções deste fabricante.',
      })
      return
    }

    try {
      setSavingCfIds((prev) => ({ ...prev, [cfId]: true }))
      const updatePayload: Record<string, any> = {}
      if (draft.incoterm !== undefined) updatePayload.incoterm = draft.incoterm
      if (draft.tempo_fabricacao !== undefined)
        updatePayload.tempo_fabricacao = draft.tempo_fabricacao
      if (draft.condicao_pagamento !== undefined)
        updatePayload.condicao_pagamento = draft.condicao_pagamento

      await pb.collection('cotacoes_fornecedor').update(cfId, updatePayload)

      // Atualiza o estado local imediatamente
      setCotacoesF((prev) =>
        prev.map((item) => (item.id === cfId ? { ...item, ...updatePayload } : item)),
      )

      // Limpa os rascunhos salvos deste fornecedor
      setCfDrafts((prev) => {
        const next = { ...prev }
        delete next[cfId]
        return next
      })

      // Se houver callback onAccepted ou recarregamento de condições da cotação
      if (onAccepted) {
        await onAccepted()
      }

      toast({
        title: 'Opções salvas com sucesso',
        description: 'Condições comerciais do fabricante atualizadas.',
      })
    } catch (err: any) {
      toast({
        title: 'Erro ao salvar opções',
        description: err.message,
        variant: 'destructive',
      })
    } finally {
      setSavingCfIds((prev) => ({ ...prev, [cfId]: false }))
    }
  }

  const handleAddFornecedor = async (id: string) => {
    if (!potencialId || !id) return
    try {
      // Pull the Incoterm and Tempo de Fabricação registered on the fornecedor
      // so they are automatically linked to this quotation.
      const fornecedor = await pb.collection('fornecedores').getOne(id)
      await pb.collection('cotacoes_fornecedor').create({
        potencial_id: potencialId,
        fornecedor_id: id,
        status: 'pendente',
        data_solicitacao: new Date().toISOString(),
        incoterm: fornecedor.incoterm || '',
        tempo_fabricacao: fornecedor.tempo_fabricacao || '',
        condicao_pagamento: fornecedor.condicao_pagamento || '',
      })
      setIsAddOpen(false)
      toast({ title: 'Fabricante adicionado' })
    } catch (err: any) {
      toast({ title: 'Erro', description: err.message, variant: 'destructive' })
    }
  }

  const handleSaveDraftPrices = async () => {
    try {
      setIsSavingDraft(true)
      const allDraftKeys = new Set([...Object.keys(draftPrices), ...Object.keys(draftMoqs)])

      const promises: Promise<any>[] = []

      for (const key of allDraftKeys) {
        const separatorIdx = key.indexOf('_')
        if (separatorIdx === -1) continue
        const cfId = key.substring(0, separatorIdx)
        const itemId = key.substring(separatorIdx + 1)

        const existingCi = cotacoesI.find(
          (c) => c.cotacao_fornecedor_id === cfId && c.item_id === itemId,
        )

        const preco =
          draftPrices[key] !== undefined ? draftPrices[key] : existingCi?.preco_ofertado || 0

        const moq =
          draftMoqs[key] !== undefined ? draftMoqs[key] : existingCi?.quantidade_minima || 0

        if (existingCi) {
          promises.push(
            pb.collection('cotacoes_itens').update(existingCi.id, {
              preco_ofertado: preco,
              quantidade_minima: moq,
            }),
          )
        } else {
          promises.push(
            pb.collection('cotacoes_itens').create({
              cotacao_fornecedor_id: cfId,
              item_id: itemId,
              preco_ofertado: preco,
              quantidade_minima: moq,
              vencedor: false,
            }),
          )
        }
      }

      for (const [cfId, drafts] of Object.entries(cfDrafts)) {
        if (!drafts || Object.keys(drafts).length === 0) continue
        const updatePayload: Record<string, any> = {}
        if (drafts.incoterm !== undefined) updatePayload.incoterm = drafts.incoterm
        if (drafts.tempo_fabricacao !== undefined)
          updatePayload.tempo_fabricacao = drafts.tempo_fabricacao
        if (drafts.condicao_pagamento !== undefined)
          updatePayload.condicao_pagamento = drafts.condicao_pagamento

        if (Object.keys(updatePayload).length > 0) {
          promises.push(pb.collection('cotacoes_fornecedor').update(cfId, updatePayload))
        }
      }

      await Promise.all(promises)

      setDraftPrices({})
      setDraftMoqs({})
      setCfDrafts({})

      await loadData()
      if (onAccepted) {
        await onAccepted()
      }

      toast({
        title: 'Edições salvas',
        description: 'Edições da cotação salvas com sucesso.',
      })
    } catch (err: any) {
      toast({
        title: 'Erro ao salvar cotação',
        description: err.message,
        variant: 'destructive',
      })
    } finally {
      setIsSavingDraft(false)
    }
  }

  const handleToggleWinner = (cfId:string,itemId:string,ofertaId?:string,_winner?:boolean,linhaId?:string) => {
    const offer=cotacoesI.find(c=>c.id===ofertaId&&c.cotacao_fornecedor_id===cfId&&c.item_id===itemId)
    if(!offer){toast({title:'Salve a oferta primeiro',description:'Preencha o preço e use Salvar Cotação antes de revisar.'});return}
    openReview([offer],linhaId)
  }

  const handleAcceptSelected = () => openReview(cotacoesI.filter(c=>c.vencedor))
  const handleAcceptCounterProposalForSupplier = (cfId:string) => openReview(cotacoesI.filter(c=>c.cotacao_fornecedor_id===cfId))

  const handleExportExcel = () => {
    let csv = 'SKU;Description;Size;Finish;Quantity;Unit;'

    cotacoesF.forEach((cf) => {
      csv += `"${(cf.expand?.fornecedor_id?.nome || '').replace(/"/g, '""')} Price";`
    })
    csv += 'Lowest Price;Target Price\n'

    potencialItens.forEach((pi) => {
      const itemNode = pi.expand?.item_id
      const desc =
        itemNode?.descricao_curta_en ||
        itemNode?.descricao_curta ||
        itemNode?.descr_en ||
        itemNode?.descr_pt ||
        ''
      const extraDesc = itemNode?.descricao_extra_en || itemNode?.descricao_extra || ''
      const combinedDesc = extraDesc ? `${desc}\n\n${extraDesc}` : desc
      const sku = (itemNode?.sku || '').replace(/"/g, '""')
      const size = (itemNode?.tamanho || '').replace(/"/g, '""')
      const finish = (
        itemNode?.expand?.acabamento_id?.nome_en ||
        itemNode?.expand?.acabamento_id?.nome_pt ||
        itemNode?.expand?.acabamento_id?.codigo ||
        ''
      ).replace(/"/g, '""')
      const qty = pi.quantidade || 0
      const unit = pi.unidade_medida || 'UN'

      let row = `"${sku}";"${combinedDesc.replace(/"/g, '""')}";"${size}";"${finish}";${qty};"${unit}";`

      let currentPrices: number[] = []

      cotacoesF.forEach((cf) => {
        const draft = draftPrices[`${cf.id}_${pi.item_id}`]
        const ci = cotacoesI.find(
          (c) => c.cotacao_fornecedor_id === cf.id && c.item_id === pi.item_id,
        )
        const price = draft !== undefined ? draft : ci?.preco_ofertado || 0
        if (price > 0) currentPrices.push(price)
        row += price > 0 ? `"${price.toFixed(3).replace('.', ',')}";` : `"";`
      })

      const offeredPrice = currentPrices.length > 0 ? Math.min(...currentPrices) : 0

      let targetPrice = 0
      const winners = cotacoesI.filter((c) => c.item_id === pi.item_id && c.vencedor)
      if (winners.length > 0) {
        const draft = draftPrices[`${winners[0].cotacao_fornecedor_id}_${pi.item_id}`]
        targetPrice = draft !== undefined && draft > 0 ? draft : winners[0].preco_ofertado || 0
      } else {
        targetPrice = offeredPrice
      }

      row += `"${offeredPrice > 0 ? offeredPrice.toFixed(3).replace('.', ',') : ''}";"${targetPrice > 0 ? targetPrice.toFixed(3).replace('.', ',') : ''}"\n`
      csv += row
    })

    const blob = new Blob(['\uFEFF' + csv], { type: 'text/csv;charset=utf-8;' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `Comparative_Matrix_${potencialId}.csv`
    a.click()
    URL.revokeObjectURL(url)
  }

  const handleExportCounterProposal = (cf: any) => {
    let csv = 'SKU;Description;Size;Finish;Quantity;Unit;MOQ;Offered Price;Target Price\n'
    potencialItens.forEach((pi) => {
      const itemNode = pi.expand?.item_id
      const desc =
        itemNode?.descricao_curta_en ||
        itemNode?.descricao_curta ||
        itemNode?.descr_en ||
        itemNode?.descr_pt ||
        ''
      const extraDesc = itemNode?.descricao_extra_en || itemNode?.descricao_extra || ''
      const combinedDesc = extraDesc ? `${desc}\n\n${extraDesc}` : desc
      const sku = (itemNode?.sku || '').replace(/"/g, '""')
      const size = (itemNode?.tamanho || '').replace(/"/g, '""')
      const finish = (
        itemNode?.expand?.acabamento_id?.nome_en ||
        itemNode?.expand?.acabamento_id?.nome_pt ||
        itemNode?.expand?.acabamento_id?.codigo ||
        ''
      ).replace(/"/g, '""')
      const qty = pi.quantidade || 0
      const unit = pi.unidade_medida || 'UN'

      const ci = cotacoesI.find(
        (c) => c.cotacao_fornecedor_id === cf.id && c.item_id === pi.item_id,
      )
      const offered = ci?.preco_ofertado || 0
      const target = ci?.preco_contraproposta > 0 ? ci.preco_contraproposta : offered
      const moq = ci?.quantidade_minima || 0

      const offeredStr = offered > 0 ? offered.toFixed(3).replace('.', ',') : ''
      const targetStr = target > 0 ? target.toFixed(3).replace('.', ',') : ''

      csv += `"${sku}";"${combinedDesc.replace(/"/g, '""')}";"${size}";"${finish}";${qty};"${unit}";${moq};"${offeredStr}";"${targetStr}"\n`
    })

    const blob = new Blob(['\uFEFF' + csv], { type: 'text/csv;charset=utf-8;' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `Counter_Proposal_${cf.expand?.fornecedor_id?.nome}.csv`
    a.click()
    URL.revokeObjectURL(url)
  }

  const handleExportForSupplier = (cf: any) => {
    let csv = 'SKU;Description;Size;Finish;Quantity;Unit;MOQ;Offered Price;Target Price\n'
    potencialItens.forEach((pi) => {
      const itemNode = pi.expand?.item_id
      const desc =
        itemNode?.descricao_curta_en ||
        itemNode?.descricao_curta ||
        itemNode?.descr_en ||
        itemNode?.descr_pt ||
        ''
      const extraDesc = itemNode?.descricao_extra_en || itemNode?.descricao_extra || ''
      const combinedDesc = extraDesc ? `${desc}\n\n${extraDesc}` : desc
      const sku = (itemNode?.sku || '').replace(/"/g, '""')
      const size = (itemNode?.tamanho || '').replace(/"/g, '""')
      const finish = (
        itemNode?.expand?.acabamento_id?.nome_en ||
        itemNode?.expand?.acabamento_id?.nome_pt ||
        itemNode?.expand?.acabamento_id?.codigo ||
        ''
      ).replace(/"/g, '""')

      csv += `"${sku}";"${combinedDesc.replace(/"/g, '""')}";"${size}";"${finish}";${pi.quantidade};"${pi.unidade_medida || 'UN'}";"";"";""\n`
    })

    const blob = new Blob(['\uFEFF' + csv], { type: 'text/csv;charset=utf-8;' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `Quotation_${cf.expand?.fornecedor_id?.nome}.csv`
    a.click()
    URL.revokeObjectURL(url)
  }

  const totals = useMemo(() => {
    let custoTotal = 0
    potencialItens.forEach((pi) => {
      const qtd = pi.quantidade || 0
      const winner = cotacoesI.find((c) => c.item_id === pi.item_id && c.vencedor)
      if (winner) {
        let draftP = draftPrices[`${winner.cotacao_fornecedor_id}_${pi.item_id}`]
        let p = draftP !== undefined ? draftP : (winner.preco_ofertado ?? 0)
        custoTotal += qtd * p
      }
    })
    return {
      custoTotal,
    }
  }, [potencialItens, cotacoesI, draftPrices])

  const formatCurrency = (val: number) =>
    val.toLocaleString('en-US', { minimumFractionDigits: 3, maximumFractionDigits: 3 })

  if (!potencialId) return <div className="p-4 text-center">Potencial não encontrado.</div>

  const availableFornecedores = fornecedores.filter(
    (f) => !cotacoesF.some((cf) => cf.fornecedor_id === f.id),
  )
  const sortedFornecedores = [...availableFornecedores]
    .filter((f) => (filterByLine ? prioritizedSuppliers.has(f.nome) : true))
    .sort((a, b) => {
      const aPrio = prioritizedSuppliers.has(a.nome)
      const bPrio = prioritizedSuppliers.has(b.nome)
      if (aPrio && !bPrio) return -1
      if (!aPrio && bPrio) return 1
      return a.nome.localeCompare(b.nome)
    })

  const filteredPotencialItens = potencialItens.filter((pi) => {
    if (!searchTerm) return true
    const haystack = [
      pi.expand?.item_id?.sku,
      pi.expand?.item_id?.descr_pt,
      pi.expand?.item_id?.descricao_curta,
      pi.expand?.item_id?.descr_en,
      pi.expand?.item_id?.descricao_curta_en,
      pi.expand?.item_id?.tamanho,
      pi.expand?.item_id?.linha_id?.nome_pt,
      pi.expand?.item_id?.acabamento_id?.nome_pt,
      pi.expand?.item_id?.acabamento_id?.codigo,
    ]
      .filter(Boolean)
      .join(' ')
    return textMatchesAll(haystack, searchTerm)
  })

  return (
    <div className="flex flex-col h-full space-y-6">
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center bg-card p-4 border rounded-xl shadow-sm gap-4 shrink-0">
        <div className="flex flex-col gap-2 shrink-0">
          <div className="flex items-center gap-3">
            <h2 className="text-2xl font-bold tracking-tight whitespace-nowrap">
              Cotação de Fabricantes
            </h2>
            <Badge
              variant="outline"
              className="bg-blue-50 text-blue-700 border border-blue-200 font-mono text-xs px-2.5 py-0.5 whitespace-nowrap"
            >
              Cotação #{potencial?.numero_potencial || potencialId}
            </Badge>
          </div>
          <div className="flex flex-col">
            <span className="text-muted-foreground font-medium text-[10px] uppercase tracking-wider">
              Custo Selecionado
            </span>
            <span className="font-mono font-bold text-lg text-green-700 leading-tight">
              $ {formatCurrency(totals.custoTotal)}
            </span>
          </div>
        </div>

        <div className="flex flex-wrap items-center justify-start lg:justify-end gap-2 w-full lg:w-auto pt-3 lg:pt-0 border-t lg:border-0">
          <div className="relative w-48 xl:w-64">
            <Search className="w-4 h-4 absolute left-2.5 top-2.5 text-muted-foreground" />
            <Input
              placeholder="Buscar SKU ou Descrição..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="h-9 pl-9 text-xs"
            />
          </div>

          <Button
            variant="ghost"
            size="icon"
            onClick={() => setIsCompact(!isCompact)}
            className="text-muted-foreground"
            title="Alternar Densidade"
          >
            {isCompact ? <Maximize2 className="w-4 h-4" /> : <Minimize2 className="w-4 h-4" />}
          </Button>

          <Popover open={isAddOpen} onOpenChange={setIsAddOpen}>
            <PopoverTrigger asChild>
              <Button variant="outline" size="sm" className="whitespace-nowrap">
                <Plus className="w-4 h-4 mr-2" /> Fabricante
              </Button>
            </PopoverTrigger>
            <PopoverContent className="w-[340px] p-0" align="start">
              <div className="p-2 border-b flex items-center justify-between bg-muted/10">
                <Label
                  className="text-xs text-muted-foreground cursor-pointer"
                  htmlFor="line-filter"
                >
                  Apenas fornecedores da linha
                </Label>
                <Switch id="line-filter" checked={filterByLine} onCheckedChange={setFilterByLine} />
              </div>
              <Command
                filter={(value, search) => {
                  return textMatchesAll(value, search) ? 1 : 0
                }}
              >
                <CommandInput
                  placeholder="Buscar fabricante..."
                  value={comboboxSearch}
                  onValueChange={setComboboxSearch}
                />
                <CommandList>
                  <CommandEmpty>Nenhum fabricante encontrado.</CommandEmpty>
                  <CommandGroup>
                    {sortedFornecedores.map((f) => (
                      <CommandItem
                        key={f.id}
                        value={f.nome}
                        onSelect={() => {
                          handleAddFornecedor(f.id)
                          setComboboxSearch('')
                        }}
                      >
                        <div className="flex items-center justify-between w-full">
                          <span className="truncate" title={f.nome}>
                            {f.nome}
                          </span>
                          <div className="flex items-center gap-1 shrink-0 ml-2">
                            {prioritizedSuppliers.has(f.nome) && (
                              <Badge
                                variant="secondary"
                                className="text-[9px] px-1 h-4 font-normal bg-emerald-50 text-emerald-700 border-emerald-200"
                              >
                                Recomendado
                              </Badge>
                            )}
                            {f.auditado && (
                              <span title="Auditado">
                                <ShieldCheck className="w-3.5 h-3.5 text-blue-600" />
                              </span>
                            )}
                            {(suppliersWithHistory.has(f.id) ||
                              suppliersWithHistory.has(f.nome)) && (
                              <span title="Possui Histórico">
                                <History className="w-3.5 h-3.5 text-muted-foreground" />
                              </span>
                            )}
                          </div>
                        </div>
                      </CommandItem>
                    ))}
                    {sortedFornecedores.length === 0 && (
                      <CommandItem disabled>Nenhum fabricante disponível</CommandItem>
                    )}
                  </CommandGroup>
                </CommandList>
              </Command>
            </PopoverContent>
          </Popover>

          <Button
            variant="outline"
            size="sm"
            onClick={() => setIsCounterOpen(true)}
            className="border-amber-200 text-amber-700 bg-amber-50 hover:bg-amber-100 hover:text-amber-800 whitespace-nowrap"
          >
            <TrendingDown className="w-4 h-4 mr-2" /> Contraproposta
          </Button>

          <Button
            variant="outline"
            size="sm"
            onClick={handleExportExcel}
            className="whitespace-nowrap"
          >
            <Download className="w-4 h-4 mr-2" /> Exportar Planilha (.csv)
          </Button>

          <Button
            variant="outline"
            size="sm"
            onClick={handleSaveDraftPrices}
            disabled={
              isSavingDraft ||
              (Object.keys(draftPrices).length === 0 &&
                Object.keys(draftMoqs).length === 0 &&
                Object.keys(cfDrafts).length === 0)
            }
            className="border-emerald-300 text-emerald-800 bg-emerald-50 hover:bg-emerald-100 hover:text-emerald-900 whitespace-nowrap"
            title="Salva as edições manuais de preço e condições sem finalizar a cotação"
          >
            {isSavingDraft ? (
              <Loader2 className="w-4 h-4 mr-2 animate-spin" />
            ) : (
              <Save className="w-4 h-4 mr-2" />
            )}
            Salvar Cotação
          </Button>

          <Button
            variant="outline"
            size="sm"
            onClick={handleAcceptSelected}
            className="border-blue-200 text-blue-700 bg-blue-50 hover:bg-blue-100 hover:text-blue-800 whitespace-nowrap"
          >
            <CheckSquare className="w-4 h-4 mr-2" /> Revisar compras selecionadas
          </Button>
        </div>
      </div>

      <div className="flex-1 overflow-auto flex flex-col gap-6 pr-1">
        <div className="border rounded-xl shadow-sm bg-card overflow-x-auto shrink-0">
          <Table>
            <TableHeader className="bg-muted/50 sticky top-0 z-20 shadow-sm">
              <TableRow>
                <TableHead className="min-w-[160px] font-semibold py-2">Item</TableHead>
                <TableHead className="font-semibold text-center w-16 py-2">Qtd</TableHead>
                <TableHead className="font-semibold text-right min-w-[90px] py-2 bg-muted/10 border-r">
                  Último Preço
                  <span className="text-[9px] font-normal text-muted-foreground block">
                    (Histórico)
                  </span>
                </TableHead>
                <TableHead className="font-semibold text-right min-w-[90px] py-2 border-r bg-muted/5">
                  Menor Oferta
                  <span className="text-[9px] font-normal text-muted-foreground block">
                    (Atual)
                  </span>
                </TableHead>
                {cotacoesF.map((cf) => (
                  <TableHead
                    key={cf.id}
                    className="min-w-[160px] bg-muted/30 border-r py-2 cursor-pointer select-none"
                    onDoubleClick={() => handleSelectAllFor(cf.id)}
                    title="Duplo clique para selecionar todos os itens deste fabricante"
                  >
                    <div className="flex flex-col items-center relative group">
                      <div className="flex items-center gap-1 w-full justify-center">
                        <Tooltip>
                          <TooltipTrigger asChild>
                            <span className="font-bold text-foreground truncate max-w-[120px] text-xs cursor-pointer">
                              {cf.expand?.fornecedor_id?.nome}
                            </span>
                          </TooltipTrigger>
                          <TooltipContent side="top">
                            <p className="font-semibold">{cf.expand?.fornecedor_id?.nome}</p>
                            <p className="text-[10px] text-muted-foreground mt-0.5">
                              Dê duplo clique para selecionar todos os itens
                            </p>
                          </TooltipContent>
                        </Tooltip>

                        {cf.expand?.fornecedor_id?.auditado && (
                          <Badge
                            variant="outline"
                            className="text-[8px] h-4 px-1 bg-blue-50 text-blue-700 border-blue-200"
                          >
                            Aud
                          </Badge>
                        )}
                        <Popover>
                          <PopoverTrigger asChild>
                            <Button
                              variant="ghost"
                              size="icon"
                              className="h-5 w-5 opacity-70 hover:opacity-100 group-hover:opacity-100"
                              onClick={(e) => e.stopPropagation()}
                              onDoubleClick={(e) => e.stopPropagation()}
                              title="Opções do Fabricante"
                            >
                              <Settings2 className="w-3 h-3" />
                            </Button>
                          </PopoverTrigger>
                          <PopoverContent
                            className="w-80 p-3"
                            align="center"
                            onClick={(e) => e.stopPropagation()}
                            onDoubleClick={(e) => e.stopPropagation()}
                          >
                            <div className="space-y-3">
                              <div className="flex items-center justify-between pb-1 border-b">
                                <h4 className="font-semibold text-xs text-foreground">
                                  Opções do Fabricante
                                </h4>
                                <span className="text-[10px] text-muted-foreground truncate max-w-[140px]">
                                  {cf.expand?.fornecedor_id?.nome}
                                </span>
                              </div>
                              <div className="space-y-1">
                                <Label className="text-xs flex items-center gap-1">
                                  <Truck className="w-3 h-3 text-muted-foreground" />
                                  Incoterm
                                  <span className="text-[9px] font-normal text-muted-foreground">
                                    (desta cotação)
                                  </span>
                                </Label>
                                <Input
                                  className="h-7 text-xs bg-white"
                                  placeholder="Ex: CIF, FOB, EXW..."
                                  value={
                                    cfDrafts[cf.id]?.incoterm !== undefined
                                      ? cfDrafts[cf.id].incoterm!
                                      : cf.incoterm || ''
                                  }
                                  onChange={(e) =>
                                    setCfDrafts((prev) => ({
                                      ...prev,
                                      [cf.id]: {
                                        ...prev[cf.id],
                                        incoterm: e.target.value,
                                      },
                                    }))
                                  }
                                  title="Editar para esta cotação (não altera o cadastro do fabricante)"
                                />
                              </div>
                              <div className="space-y-1">
                                <Label className="text-xs flex items-center gap-1">
                                  <Clock className="w-3 h-3 text-muted-foreground" />
                                  Tempo de Fabricação
                                  <span className="text-[9px] font-normal text-muted-foreground">
                                    (desta cotação)
                                  </span>
                                </Label>
                                <Input
                                  className="h-7 text-xs bg-white"
                                  placeholder="Ex: 30 a 45 dias..."
                                  value={
                                    cfDrafts[cf.id]?.tempo_fabricacao !== undefined
                                      ? cfDrafts[cf.id].tempo_fabricacao!
                                      : cf.tempo_fabricacao || ''
                                  }
                                  onChange={(e) =>
                                    setCfDrafts((prev) => ({
                                      ...prev,
                                      [cf.id]: {
                                        ...prev[cf.id],
                                        tempo_fabricacao: e.target.value,
                                      },
                                    }))
                                  }
                                  title="Editar para esta cotação (não altera o cadastro do fabricante)"
                                />
                              </div>
                              <div className="space-y-1">
                                <Label className="text-xs flex items-center gap-1">
                                  <CreditCard className="w-3 h-3 text-muted-foreground" />
                                  Condição de Pagamento
                                  <span className="text-[9px] font-normal text-muted-foreground">
                                    (desta cotação)
                                  </span>
                                </Label>
                                <Input
                                  className="h-7 text-xs bg-white"
                                  placeholder="Ex: 30% sinal + 70% embarque..."
                                  value={
                                    cfDrafts[cf.id]?.condicao_pagamento !== undefined
                                      ? cfDrafts[cf.id].condicao_pagamento!
                                      : cf.condicao_pagamento || ''
                                  }
                                  onChange={(e) =>
                                    setCfDrafts((prev) => ({
                                      ...prev,
                                      [cf.id]: {
                                        ...prev[cf.id],
                                        condicao_pagamento: e.target.value,
                                      },
                                    }))
                                  }
                                  title="Editar para esta cotação (não altera o cadastro do fabricante)"
                                />
                              </div>
                              {/* Botão de salvar no painel */}
                              {(() => {
                                const hasDraftChanges =
                                  cfDrafts[cf.id] !== undefined &&
                                  (cfDrafts[cf.id]?.incoterm !== undefined ||
                                    cfDrafts[cf.id]?.tempo_fabricacao !== undefined ||
                                    cfDrafts[cf.id]?.condicao_pagamento !== undefined)
                                const isSavingThisCf = !!savingCfIds[cf.id]

                                return (
                                  <Button
                                    size="sm"
                                    className="w-full text-xs h-7 bg-emerald-600 hover:bg-emerald-700 text-white font-medium gap-1.5 shadow-xs"
                                    disabled={isSavingThisCf || !hasDraftChanges}
                                    onClick={() => handleSaveSupplierOptions(cf.id)}
                                  >
                                    {isSavingThisCf ? (
                                      <Loader2 className="w-3.5 h-3.5 animate-spin" />
                                    ) : (
                                      <Save className="w-3.5 h-3.5" />
                                    )}
                                    {isSavingThisCf ? 'Salvando...' : 'Salvar Condições'}
                                  </Button>
                                )
                              })()}
                              <div className="pt-2 border-t flex flex-col gap-1.5">
                                {(() => {
                                  const countWithCounter = cotacoesI.filter(
                                    (c) =>
                                      c.cotacao_fornecedor_id === cf.id &&
                                      c.preco_contraproposta > 0,
                                  ).length
                                  return (
                                    <Button
                                      variant="outline"
                                      size="sm"
                                      className="w-full justify-start text-xs h-7 bg-amber-50 hover:bg-amber-100 text-amber-800 border-amber-200 font-medium"
                                      disabled={!cotacoesI.some(c=>c.cotacao_fornecedor_id===cf.id)}
                                      title={
                                        countWithCounter > 0
                                          ? `Revisa as respostas e a compra dos itens deste fabricante`
                                          : 'Revisar a resposta recebida do fabricante'
                                      }
                                      onClick={() => handleAcceptCounterProposalForSupplier(cf.id)}
                                    >
                                      <TrendingDown className="w-3 h-3 mr-2 text-amber-600" />
                                      Revisar resposta e compra{' '}
                                      {countWithCounter > 0 && `(${countWithCounter})`}
                                    </Button>
                                  )
                                })()}
                                <Button
                                  variant="outline"
                                  size="sm"
                                  className="w-full justify-start text-xs h-7"
                                  onClick={() => handleExportForSupplier(cf)}
                                >
                                  <Download className="w-3 h-3 mr-2" /> Planilha para Preenchimento
                                </Button>
                                <Button
                                  variant="outline"
                                  size="sm"
                                  className="w-full justify-start text-xs h-7"
                                  onClick={() => handleExportCounterProposal(cf)}
                                >
                                  <Download className="w-3 h-3 mr-2" /> Exportar Contra-proposta
                                </Button>
                                <Button
                                  variant="outline"
                                  size="sm"
                                  className="w-full justify-start text-xs h-7"
                                  onClick={() => handleSelectAllFor(cf.id)}
                                >
                                  <CheckSquare className="w-3 h-3 mr-2" /> Revisar todos
                                </Button>
                                <div className="relative w-full">
                                  <Input
                                    type="file"
                                    accept=".csv,.xlsx,.xls"
                                    className="absolute inset-0 opacity-0 cursor-pointer"
                                    onChange={(e) =>
                                      e.target.files?.[0] &&
                                      handleFileSelect(cf.id, e.target.files[0])
                                    }
                                  />
                                  <Button
                                    variant="outline"
                                    size="sm"
                                    className="w-full justify-start text-xs h-7 pointer-events-none"
                                  >
                                    <FileUp className="w-3 h-3 mr-2" /> Importar Preços
                                  </Button>
                                </div>
                              </div>{' '}
                            </div>
                          </PopoverContent>
                        </Popover>
                      </div>

                      {(() => {
                        const isFinalizada = cf.status === 'finalizada'
                        return isFinalizada ? (
                          <Badge
                            variant="secondary"
                            className="mt-0.5 text-[9px] h-3.5 bg-muted-foreground/10 text-muted-foreground"
                          >
                            Finalizada
                          </Badge>
                        ) : (
                          <Badge
                            variant="outline"
                            className="mt-0.5 text-[9px] h-3.5 border-amber-300 text-amber-700 bg-amber-50"
                          >
                            Pendente
                          </Badge>
                        )
                      })()}

                      {/* Informações comerciais desta cotação (Incoterm, Fabricação, Pagamento) */}
                      {(() => {
                        const effectiveIncoterm =
                          cfDrafts[cf.id]?.incoterm !== undefined
                            ? cfDrafts[cf.id].incoterm
                            : cf.incoterm || cf.expand?.fornecedor_id?.incoterm || ''
                        const effectiveTempo =
                          cfDrafts[cf.id]?.tempo_fabricacao !== undefined
                            ? cfDrafts[cf.id].tempo_fabricacao
                            : cf.tempo_fabricacao ||
                              cf.expand?.fornecedor_id?.tempo_fabricacao ||
                              ''
                        const effectivePagamento =
                          cfDrafts[cf.id]?.condicao_pagamento !== undefined
                            ? cfDrafts[cf.id].condicao_pagamento
                            : cf.condicao_pagamento ||
                              cf.expand?.fornecedor_id?.condicao_pagamento ||
                              ''

                        const hasAnyCondition =
                          !!effectiveIncoterm || !!effectiveTempo || !!effectivePagamento

                        if (!hasAnyCondition) {
                          return (
                            <span className="text-[9px] text-muted-foreground/60 italic mt-1">
                              Sem condições cadastradas
                            </span>
                          )
                        }

                        return (
                          <div className="w-full flex flex-col gap-0.5 mt-1 pt-1 border-t border-border/50 text-[10px] text-left">
                            {effectiveIncoterm && (
                              <Tooltip>
                                <TooltipTrigger asChild>
                                  <div className="flex items-center gap-1 text-muted-foreground hover:text-foreground cursor-default">
                                    <Truck className="w-2.5 h-2.5 shrink-0 text-blue-600" />
                                    <span className="font-medium text-foreground shrink-0 text-[9px]">
                                      Incoterm:
                                    </span>
                                    <span className="truncate font-semibold text-[9px] text-blue-700 bg-blue-50/70 px-1 py-0.2 rounded border border-blue-200/60 max-w-[100px]">
                                      {effectiveIncoterm}
                                    </span>
                                  </div>
                                </TooltipTrigger>
                                <TooltipContent side="bottom" className="text-xs">
                                  <p>
                                    <strong>Incoterm:</strong> {effectiveIncoterm}
                                  </p>
                                </TooltipContent>
                              </Tooltip>
                            )}

                            {effectiveTempo && (
                              <Tooltip>
                                <TooltipTrigger asChild>
                                  <div className="flex items-center gap-1 text-muted-foreground hover:text-foreground cursor-default">
                                    <Clock className="w-2.5 h-2.5 shrink-0 text-blue-600" />
                                    <span className="font-medium text-foreground shrink-0 text-[9px]">
                                      Fabricação:
                                    </span>
                                    <span className="truncate text-[9px] text-muted-foreground max-w-[100px]">
                                      {effectiveTempo}
                                    </span>
                                  </div>
                                </TooltipTrigger>
                                <TooltipContent side="bottom" className="text-xs">
                                  <p>
                                    <strong>Tempo de Fabricação:</strong> {effectiveTempo}
                                  </p>
                                </TooltipContent>
                              </Tooltip>
                            )}

                            {effectivePagamento && (
                              <Tooltip>
                                <TooltipTrigger asChild>
                                  <div className="flex items-center gap-1 text-muted-foreground hover:text-foreground cursor-default">
                                    <CreditCard className="w-2.5 h-2.5 shrink-0 text-blue-600" />
                                    <span className="font-medium text-foreground shrink-0 text-[9px]">
                                      Pagamento:
                                    </span>
                                    <span className="truncate text-[9px] text-muted-foreground max-w-[100px]">
                                      {effectivePagamento}
                                    </span>
                                  </div>
                                </TooltipTrigger>
                                <TooltipContent side="bottom" className="text-xs">
                                  <p>
                                    <strong>Condição de Pagamento:</strong> {effectivePagamento}
                                  </p>
                                </TooltipContent>
                              </Tooltip>
                            )}
                          </div>
                        )
                      })()}
                    </div>
                  </TableHead>
                ))}
              </TableRow>
            </TableHeader>
            <TableBody>
              {filteredPotencialItens.length === 0 ? (
                <TableRow>
                  <TableCell
                    colSpan={4 + cotacoesF.length}
                    className="h-32 text-center text-muted-foreground"
                  >
                    {potencialItens.length === 0
                      ? 'Nenhum item adicionado a este potencial.'
                      : 'Nenhum item encontrado para a busca.'}
                  </TableCell>
                </TableRow>
              ) : (
                filteredPotencialItens.map((pi) => {
                  const currentPrices = cotacoesF.map((cf) => {
                    const ci = cotacoesI.find(
                      (c) => c.cotacao_fornecedor_id === cf.id && c.item_id === pi.item_id,
                    )
                    const draft = draftPrices[`${cf.id}_${pi.item_id}`]
                    if (draft !== undefined) return draft
                    return ci?.preco_ofertado || 0
                  })
                  const validCurrentPrices = currentPrices.filter((p) => p > 0)
                  const lowestCurrentPrice =
                    validCurrentPrices.length > 0 ? Math.min(...validCurrentPrices) : undefined

                  return (
                    <TableRow key={pi.id} className="group hover:bg-transparent">
                      <TableCell
                        className={cn('align-top px-3 border-r', isCompact ? 'py-1' : 'py-1.5')}
                      >
                        {(() => {
                          const extraDesc =
                            pi.expand?.item_id?.descricao_extra_en ||
                            pi.expand?.item_id?.descricao_extra ||
                            ''
                          const content = (
                            <div className={cn(extraDesc && 'cursor-help')}>
                              <div className="font-semibold text-xs">{pi.expand?.item_id?.sku}</div>
                              <div className="text-[10px] text-muted-foreground line-clamp-2 pr-2">
                                {pi.expand?.item_id?.descr_en ||
                                  pi.expand?.item_id?.descricao_curta}
                              </div>
                            </div>
                          )

                          return extraDesc ? (
                            <Tooltip>
                              <TooltipTrigger asChild>{content}</TooltipTrigger>
                              <TooltipContent
                                side="right"
                                className="max-w-[300px] whitespace-pre-wrap text-xs"
                              >
                                {extraDesc}
                              </TooltipContent>
                            </Tooltip>
                          ) : (
                            content
                          )
                        })()}
                      </TableCell>
                      <TableCell
                        className={cn(
                          'align-top px-2 text-center border-r',
                          isCompact ? 'py-1' : 'py-1.5',
                        )}
                      >
                        <span className="font-medium text-sm">{pi.quantidade}</span>
                        <span className="text-[9px] text-muted-foreground block">
                          {pi.unidade_medida || 'UN'}
                        </span>
                      </TableCell>

                      <TableCell
                        className={cn(
                          'align-middle px-2 text-right border-r bg-muted/10',
                          isCompact ? 'py-1' : 'py-1.5',
                        )}
                      >
                        {(() => {
                          const hist = latestHistorico[pi.item_id]
                          if (hist && hist.preco > 0) {
                            return (
                              <Tooltip>
                                <TooltipTrigger asChild>
                                  <span className="font-mono text-xs text-blue-600 font-bold cursor-help underline decoration-dashed underline-offset-2">
                                    $ {formatCurrency(hist.preco)}
                                  </span>
                                </TooltipTrigger>
                                <TooltipContent>
                                  <p className="font-semibold">
                                    Fornecedor: {hist.fornecedor || 'Não informado'}
                                  </p>
                                  <p className="text-xs text-muted-foreground">
                                    Data do Preço:{' '}
                                    {new Date(hist.data_cotacao).toLocaleDateString()}
                                  </p>
                                </TooltipContent>
                              </Tooltip>
                            )
                          }
                          return (
                            <span className="font-mono text-xs text-blue-600 font-bold">N/A</span>
                          )
                        })()}
                      </TableCell>

                      <TableCell
                        className={cn(
                          'align-middle px-2 text-right border-r bg-emerald-50/40',
                          isCompact ? 'py-1' : 'py-1.5',
                        )}
                      >
                        {lowestCurrentPrice ? (
                          <span className="font-mono text-xs text-emerald-700 font-bold">
                            $ {formatCurrency(lowestCurrentPrice)}
                          </span>
                        ) : (
                          <span className="text-muted-foreground">-</span>
                        )}
                      </TableCell>

                      {cotacoesF.map((cf) => {
                        const ci = cotacoesI.find(
                          (c) => c.cotacao_fornecedor_id === cf.id && c.item_id === pi.item_id,
                        )
                        const draft = draftPrices[`${cf.id}_${pi.item_id}`]
                        const currentPrice = draft !== undefined ? draft : ci?.preco_ofertado || 0
                        const isWinnerCell = ci?.vencedor

                        return (
                          <TableCell
                            key={cf.id}
                            className={cn(
                              'align-top px-1 border-r transition-colors relative',
                              isCompact ? 'py-0.5' : 'py-1',
                              isWinnerCell
                                ? 'bg-blue-100/70'
                                : 'bg-background/50 hover:bg-muted/20',
                            )}
                          >
                            <PriceCell
                              cotacaoF={cf}
                              item={pi}
                              cotacaoI={ci}
                              draftPrice={draft}
                              draftMoq={draftMoqs[`${cf.id}_${pi.item_id}`]}
                              isLowest={currentPrice > 0 && currentPrice === lowestCurrentPrice}
                              onDraftChange={(cfId: string, itemId: string, val: number) =>
                                setDraftPrices((p) => ({ ...p, [`${cfId}_${itemId}`]: val }))
                              }
                              onDraftMoqChange={(cfId: string, itemId: string, val: number) =>
                                setDraftMoqs((p) => ({ ...p, [`${cfId}_${itemId}`]: val }))
                              }
                              onToggleWinner={handleToggleWinner}
                            />
                          </TableCell>
                        )
                      })}
                    </TableRow>
                  )
                })
              )}
            </TableBody>
            <TableFooter className="bg-muted/30 border-t">
              <TableRow>
                <TableCell colSpan={4} className="text-right font-semibold py-2 border-r text-xs">
                  Valor Total:
                </TableCell>
                {cotacoesF.map((cf) => {
                  let total = 0
                  potencialItens.forEach((pi) => {
                    const ci = cotacoesI.find(
                      (c) => c.cotacao_fornecedor_id === cf.id && c.item_id === pi.item_id,
                    )
                    const draft = draftPrices[`${cf.id}_${pi.item_id}`]
                    const price = draft !== undefined ? draft : (ci?.preco_ofertado ?? 0)
                    total += price * (pi.quantidade || 0)
                  })
                  return (
                    <TableCell
                      key={`tot-${cf.id}`}
                      className="text-center font-mono font-bold py-2 border-r text-foreground bg-background/50 text-xs text-green-700"
                    >
                      $ {formatCurrency(total)}
                    </TableCell>
                  )
                })}
              </TableRow>
              <TableRow className="bg-amber-50/50">
                <TableCell
                  colSpan={4}
                  className="text-right font-semibold py-2 border-r text-xs text-amber-700"
                >
                  Total Selecionado (Parcial):
                </TableCell>
                {cotacoesF.map((cf) => {
                  let selectedTotal = 0
                  potencialItens.forEach((pi) => {
                    const ci = cotacoesI.find(
                      (c) => c.cotacao_fornecedor_id === cf.id && c.item_id === pi.item_id,
                    )
                    if (ci?.vencedor) {
                      const draft = draftPrices[`${cf.id}_${pi.item_id}`]
                      const price = draft !== undefined ? draft : (ci.preco_ofertado ?? 0)
                      selectedTotal += price * (pi.quantidade || 0)
                    }
                  })
                  return (
                    <TableCell
                      key={`sel-${cf.id}`}
                      className="text-center font-mono font-bold py-2 border-r text-amber-700 bg-amber-50/50 text-xs"
                    >
                      $ {formatCurrency(selectedTotal)}
                    </TableCell>
                  )
                })}
              </TableRow>
            </TableFooter>
          </Table>
        </div>
        <div className="shrink-0 flex flex-col gap-4 mb-4">
          <QuotationNotes potencialId={potencialId} cotacoesF={cotacoesF} />
        </div>
      </div>

      <CounterProposalModal
        open={isCounterOpen}
        onOpenChange={setIsCounterOpen}
        cotacoesI={cotacoesI}
        potencialItens={potencialItens}
        cotacoesF={cotacoesF}
        onSaved={loadData}
        onReviewOffer={(id:string)=>{setIsCounterOpen(false);openReview(cotacoesI.filter(c=>c.id===id))}}
      />

      <ImportMappingModal
        open={importState?.open || false}
        onOpenChange={(open: boolean) =>
          setImportState((prev) => (prev ? { ...prev, open } : null))
        }
        headers={importState?.headers || []}
        summary={{ total: importState ? importState.rows.length - 1 : 0 }}
        onConfirm={handleConfirmImport}
      />

      <PurchaseReviewDialog items={reviewItems} onClose={()=>setReviewItems([])} onConfirmed={()=>{void loadData();onAccepted?.()}} />

    </div>
  )
}

import { Trash2, ChevronUp, ChevronDown } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { FormattedInput } from '@/components/FormattedInput'
import { Badge } from '@/components/ui/badge'
import { getContrastColor, cn } from '@/lib/utils'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip'
import type { SelectedItemRecord, SelectedItemData } from '../AddItemsToPotential'
import pb from '@/lib/pocketbase/client'

interface SelectedItemsTableProps {
  selectedItems: SelectedItemRecord[]
  handleUpdateItem: (id: string, field: keyof SelectedItemData, value: string) => void
  handleRemoveItem: (id: string) => void
  handleMoveUp: (index: number) => void
  handleMoveDown: (index: number) => void
  setIsSelecting: (selecting: boolean) => void
  lastOfferedPrices: Record<string, number>
}

// Fórmula aprovada: venda = compra / (1 - margem/100). Sem markup invertido.
const computeVendaFromMargem = (compra: number, margem: number): number => {
  if (!isFinite(compra) || !isFinite(margem)) return compra
  if (margem >= 100) return compra
  return compra / (1 - margem / 100)
}

export function SelectedItemsTable({
  selectedItems,
  handleUpdateItem,
  handleRemoveItem,
  handleMoveUp,
  handleMoveDown,
  setIsSelecting,
  lastOfferedPrices,
}: SelectedItemsTableProps) {
  if (selectedItems.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-32 text-muted-foreground bg-white">
        <p className="mb-3 text-sm">Nenhum item selecionado para esta cotação.</p>
        <Button variant="outline" size="sm" onClick={() => setIsSelecting(true)}>
          Adicionar Itens
        </Button>
      </div>
    )
  }

  // minDec/maxDec: exibição exata — o total da linha usa a mesma precisão do
  // unitário exibido/salvo, sem casas ocultas.
  const formatCurrency = (value: number | '', minDec = 2, maxDec = 3, currency = 'USD') => {
    if (value === '') return '-'
    const num = Number(value)
    return isNaN(num)
      ? '-'
      : `${currency} ${num.toLocaleString('en-US', { minimumFractionDigits: minDec, maximumFractionDigits: maxDec })}`
  }

  // Precisão por linha (2 ou 3 casas). Reduzir para 2 arredonda o preço para
  // que o valor exibido continue sendo exatamente o salvo.
  const handlePrecisionChange = async (record: SelectedItemRecord, value: string) => {
    const p = value === '3' ? 3 : 2
    const unitRaw = Number(record.data.preco_unitario)
    const rounded = p === 2 && Number.isFinite(unitRaw) ? Number(unitRaw.toFixed(2)) : unitRaw
    handleUpdateItem(record.id, 'precisao_preco', String(p))
    if (p === 2 && Number.isFinite(unitRaw)) {
      handleUpdateItem(record.id, 'preco_unitario', String(rounded))
    }
    if (record.recordId && record.recordId.length === 15) {
      const payload: Record<string, number> = { precisao_preco: p }
      if (p === 2 && Number.isFinite(unitRaw)) payload.preco_unitario = rounded
      try {
        await pb.collection('potencial_itens').update(record.recordId, payload)
      } catch (err) {
        console.error('Auto-save precision failed', err)
      }
    }
  }

  const handleQuantityBlur = async (recordId: string | undefined, quantidade: string | number) => {
    if (recordId && recordId.length === 15) {
      try {
        await pb
          .collection('potencial_itens')
          .update(recordId, { quantidade: Number(quantidade) || 0 })
      } catch (err) {
        console.error('Auto-save quantity failed', err)
      }
    }
  }

  const handlePriceBlur = async (recordId: string | undefined, preco: string | number) => {
    if (recordId && recordId.length === 15) {
      try {
        await pb
          .collection('potencial_itens')
          .update(recordId, { preco_unitario: Number(preco) || 0 })
      } catch (err) {
        console.error('Auto-save price failed', err)
      }
    }
  }

  // A margem global é controlada SOMENTE pelo comando único no cabeçalho da
  // tela (PotentialDetailsWrapper) — não há controle duplicado aqui.

  return (
    <div className="flex-1 flex flex-col bg-white overflow-hidden">
      <div className="flex items-center justify-end p-2 border-b bg-slate-50/50 shrink-0">
        <div className="text-xs text-muted-foreground font-medium pr-2">
          {selectedItems.length} {selectedItems.length === 1 ? 'item' : 'itens'}
        </div>
      </div>
      <div className="flex-1 overflow-auto">
        <Table className="w-full">
          <TableHeader className="sticky top-0 bg-white z-10 shadow-sm">
            <TableRow className="h-8">
              <TableHead className="w-10 px-1"></TableHead>
              <TableHead className="w-24 text-[11px] px-4">SKU</TableHead>
              <TableHead className="w-auto text-[11px]">Descrição Curta</TableHead>
              <TableHead className="w-20 text-[11px]">Tamanho</TableHead>
              <TableHead className="w-24 text-[11px]">Acabamento</TableHead>
              <TableHead className="w-16 text-[11px] text-center">Unidade</TableHead>
              <TableHead className="w-20 text-[11px]">Quant.</TableHead>
              <TableHead className="w-24 text-[11px] text-right">
                <Tooltip>
                  <TooltipTrigger className="cursor-help underline decoration-dashed underline-offset-2">
                    Último Preço Ofertado
                  </TooltipTrigger>
                  <TooltipContent>
                    <p className="text-xs font-semibold">Último Preço Ofertado ao Cliente</p>
                    <p className="text-[10px] text-muted-foreground mt-1 max-w-[150px] leading-tight">
                      Preço mais recente ofertado a clientes em outras cotações.
                    </p>
                  </TooltipContent>
                </Tooltip>
              </TableHead>
              <TableHead className="w-24 text-[11px] text-right text-amber-600">
                <Tooltip>
                  <TooltipTrigger className="cursor-help underline decoration-dashed underline-offset-2">
                    Preço de Compra Selecionado
                  </TooltipTrigger>
                  <TooltipContent>
                    <p className="text-xs font-semibold">Preço de Compra Selecionado</p>
                    <p className="text-[10px] text-muted-foreground mt-1 max-w-[170px] leading-tight">
                      Preço da oferta escolhida para este item na cotação de fabricantes.
                    </p>
                  </TooltipContent>
                </Tooltip>
              </TableHead>
              <TableHead className="w-24 text-[11px] text-right">Margem de Venda (%)</TableHead>
              <TableHead className="w-28 text-[11px] text-right">Preço de Venda</TableHead>
              <TableHead className="w-14 text-[11px] text-center">
                <Tooltip>
                  <TooltipTrigger className="cursor-help underline decoration-dashed underline-offset-2">
                    Prec.
                  </TooltipTrigger>
                  <TooltipContent>
                    <p className="text-xs font-semibold">Precisão do preço</p>
                    <p className="text-[10px] text-muted-foreground mt-1 max-w-[160px] leading-tight">
                      Casas decimais (2 ou 3) usadas para exibir e salvar o preço de venda desta
                      linha.
                    </p>
                  </TooltipContent>
                </Tooltip>
              </TableHead>
              <TableHead className="w-24 text-[11px] text-right">Total</TableHead>
              <TableHead className="w-10 text-center text-[11px]">Ação</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {selectedItems.map((record, index) => {
              const { id, data } = record
              // Precisão por linha (2 ou 3 casas); fallback 2 quando ausente/vazia.
              const precisao = data.precisao_preco === 3 ? 3 : 2
              // O total usa EXATAMENTE o unitário exibido/salvo, na mesma precisão.
              const unitario =
                typeof data.preco_unitario === 'number'
                  ? Number(data.preco_unitario.toFixed(precisao))
                  : 0
              const total =
                Math.round((Number(data.quantidade) || 0) * Math.round(unitario * 1000)) / 1000

              const acabamento = data.item.expand?.acabamento_id
              const descricao = data.item.descricao_curta || data.item.descr_pt || '-'

              return (
                <TableRow key={id} className="h-10 py-0 group">
                  <TableCell className="px-1 py-1 w-10 align-middle">
                    <div className="flex flex-col gap-0 items-center opacity-0 group-hover:opacity-100 transition-opacity">
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-4 w-4"
                        onClick={() => handleMoveUp(index)}
                        disabled={index === 0}
                      >
                        <ChevronUp className="h-3 w-3" />
                      </Button>
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-4 w-4"
                        onClick={() => handleMoveDown(index)}
                        disabled={index === selectedItems.length - 1}
                      >
                        <ChevronDown className="h-3 w-3" />
                      </Button>
                    </div>
                  </TableCell>
                  <TableCell className="py-1 text-[10px] font-normal px-4 font-mono whitespace-nowrap">
                    {data.item.sku || '-'}
                  </TableCell>
                  <TableCell className="py-1 text-[11px] whitespace-normal leading-tight">
                    <Tooltip>
                      <TooltipTrigger asChild>
                        <span
                          className={cn(
                            data.item.descricao_extra
                              ? 'cursor-help underline decoration-dashed underline-offset-2'
                              : 'cursor-default',
                          )}
                        >
                          {descricao}
                        </span>
                      </TooltipTrigger>
                      {data.item.descricao_extra && (
                        <TooltipContent className="max-w-xs text-xs">
                          {data.item.descricao_extra}
                        </TooltipContent>
                      )}
                    </Tooltip>
                  </TableCell>
                  <TableCell className="py-1 text-[11px] whitespace-nowrap">
                    {data.item.tamanho || '-'}
                  </TableCell>
                  <TableCell className="py-1 text-xs">
                    {acabamento ? (
                      <Badge
                        style={{
                          backgroundColor: acabamento.cor_hex || '#e2e8f0',
                          color: getContrastColor(acabamento.cor_hex || '#e2e8f0'),
                        }}
                        className="whitespace-nowrap border-0 shadow-none font-medium px-2 py-0 h-5 text-[10px] rounded-full"
                      >
                        {acabamento.nome_pt}
                      </Badge>
                    ) : (
                      '-'
                    )}
                  </TableCell>
                  <TableCell className="py-1 text-xs text-center text-muted-foreground bg-slate-50/50">
                    {data.unidade_medida || data.item.unidade || '-'}
                  </TableCell>
                  <TableCell className="py-1">
                    <FormattedInput
                      className="h-7 w-16 px-2 text-right text-xs bg-white"
                      value={data.quantidade}
                      onValueChange={(val) => {
                        if (Number(val) < 0) return
                        handleUpdateItem(id, 'quantidade', val)
                      }}
                      onBlur={() => handleQuantityBlur(record.recordId, data.quantidade)}
                    />
                  </TableCell>
                  <TableCell className="py-1 text-xs text-right font-mono whitespace-nowrap text-blue-600">
                    {lastOfferedPrices[data.item.id]
                      ? formatCurrency(lastOfferedPrices[data.item.id])
                      : '—'}
                  </TableCell>
                  <TableCell className="py-1 text-xs text-right font-mono text-amber-700 font-semibold whitespace-nowrap bg-amber-50/40">
                    {(() => {
                      const hasSnapshot =
                        typeof data.referencia_preco === 'number' && data.referencia_preco > 0
                      const refPrice = hasSnapshot ? data.referencia_preco : null
                      const refSupplier = data.referencia_fornecedor
                      const refDate = data.referencia_data

                      if (!refPrice) {
                        return (
                          <span className="font-mono text-xs text-amber-600/70 font-semibold">
                            N/A
                          </span>
                        )
                      }

                      return (
                        <Tooltip>
                          <TooltipTrigger asChild>
                            <div className="flex flex-col cursor-help items-end">
                              <span className="font-bold text-amber-700">
                                {formatCurrency(refPrice, 2, 3, data.moeda_compra || 'USD')}
                              </span>
                              {refSupplier ? (
                                <span
                                  className="text-[9px] text-amber-900/80 font-medium truncate max-w-[90px]"
                                  title={refSupplier}
                                >
                                  {refSupplier}
                                </span>
                              ) : (
                                <span className="text-[9px] text-muted-foreground">-</span>
                              )}
                            </div>
                          </TooltipTrigger>
                          <TooltipContent>
                            <p className="font-semibold text-xs">
                              Preço de Compra Selecionado: {formatCurrency(refPrice, 2, 3, data.moeda_compra || 'USD')}
                            </p>
                            <p className="text-xs text-muted-foreground mt-0.5">
                              Fornecedor: {refSupplier || 'Não informado'}
                            </p>
                            {refDate && (
                              <p className="text-[10px] text-muted-foreground">
                                Data: {new Date(refDate).toLocaleDateString()}
                              </p>
                            )}
                            <p className="text-[10px] text-amber-600 font-medium mt-1">
                              Definido na Cotação de Fabricantes
                            </p>
                          </TooltipContent>
                        </Tooltip>
                      )
                    })()}
                  </TableCell>
                  <TableCell className="py-1 text-right">
                    <FormattedInput
                      className="h-7 w-20 px-2 text-right text-xs bg-white ml-auto"
                      value={(() => {
                        const hasSnapshot =
                          typeof data.referencia_preco === 'number' && data.referencia_preco > 0
                        const custo = hasSnapshot ? Number(data.referencia_preco) : 0
                        const venda = Number(data.preco_unitario)
                        if (venda > 0 && custo > 0) {
                          return ((1 - custo / venda) * 100).toFixed(2)
                        }
                        return ''
                      })()}
                      onValueChange={(val) => {
                        const m = parseFloat(val.replace(',', '.'))
                        const hasSnapshot =
                          typeof data.referencia_preco === 'number' && data.referencia_preco > 0
                        const custo = hasSnapshot ? Number(data.referencia_preco) : 0
                        if (custo === 0 || isNaN(m) || m < 0 || m >= 100) return
                        const newVenda = computeVendaFromMargem(custo, m)
                        handleUpdateItem(id, 'preco_unitario', newVenda.toFixed(precisao))
                      }}
                      onBlur={() => {
                        let parsed = parseFloat(String(data.preco_unitario))
                        if (isNaN(parsed)) parsed = 0
                        handlePriceBlur(record.recordId, parsed)
                      }}
                    />
                  </TableCell>
                  <TableCell className="py-1 text-right">
                    <FormattedInput
                      isPrice
                      fractionDigits={precisao}
                      prefixText={data.moeda_compra || 'USD'}
                      className="h-7 w-24 px-2 text-right text-xs bg-white font-bold ml-auto"
                      value={
                        typeof data.preco_unitario === 'number'
                          ? unitario.toFixed(precisao)
                          : data.preco_unitario
                      }
                      onValueChange={(val) => handleUpdateItem(id, 'preco_unitario', val)}
                      onBlur={() => {
                        let parsed = parseFloat(String(data.preco_unitario))
                        if (isNaN(parsed)) parsed = 0
                        const normalizado = Number(parsed.toFixed(precisao))
                        handleUpdateItem(id, 'preco_unitario', String(normalizado))
                        handlePriceBlur(record.recordId, normalizado)
                      }}
                    />
                  </TableCell>
                  <TableCell className="py-1 text-center">
                    <select
                      className="h-7 w-12 rounded-md border bg-white text-xs text-center"
                      title="Precisão do preço (casas decimais)"
                      value={precisao}
                      onChange={(e) => handlePrecisionChange(record, e.target.value)}
                    >
                      <option value={2}>2</option>
                      <option value={3}>3</option>
                    </select>
                  </TableCell>
                  <TableCell className="py-1 text-xs font-semibold text-right whitespace-nowrap">
                    {formatCurrency(total, 2, precisao, data.moeda_compra || 'USD')}
                  </TableCell>
                  <TableCell className="py-1 text-center">
                    <Button
                      variant="ghost"
                      size="icon"
                      className="h-6 w-6 text-muted-foreground hover:text-destructive"
                      onClick={() => handleRemoveItem(id)}
                    >
                      <Trash2 className="h-3 w-3" />
                    </Button>
                  </TableCell>
                </TableRow>
              )
            })}
          </TableBody>
        </Table>
      </div>
    </div>
  )
}

/** LOCAL CANDIDATE. Both server routes remain authenticated and unconditionally 503.
 * The candidate UI now uses these routes; no client CRUD fallback. See review/LOCAL_REVIEW.md for schema and activation prerequisites.
 * Authorization requires explicit server-side user capability and PocketBase canAccessRecord with current collection rules inside
 * the writer transaction. No client permission flag or static team-role substitute.
 * Margin editing must use salvarMargemNegociada atomically; ordinary REST PATCH is
 * not a compare-and-swap and must not be presented as concurrent-edit protection.
 */
/** Versão da margem negociada: 0/vazio = nunca editada; incrementada a cada edição autorizada e a cada consumo pela confirmação. */
export type MargemVersao = number

import pb from '../lib/pocketbase/client'
import { ClientResponseError } from 'pocketbase'

// ---------- tipos do payload ----------

export interface ConfirmarCompraPayload {
  /** Id da oferta vencedora em cotacoes_itens. Obrigatório. */
  cotacao_iten_id: string
  /**
   * Id obrigatório do registro em potencial_itens a atualizar.
   */
  potencial_iten_id: string
  /** Recorded supplier response/received offer, never the C2 target. */
  rodada_resposta_id: string
  /** updated timestamps of supplier quote, potential item, potential, supplier, catalog item, response. */
  versoes_esperadas: Record<string, string>
  /**
   * Optimistic concurrency: valor `updated` do registro cotacoes_itens lido
   * pelo cliente. Se divergir do vigente no servidor, a confirmação é rejeitada.
   */
  versao: string
  /** Chave de idempotência durável (retry seguro). Obrigatória, 8 a 120 caracteres. */
  idempotency_key: string
  /**
   * Ajuste explícito de quantidade ao MOQ quando quantidade < moq.
   * Sem a flag, quantidade abaixo do MOQ é rejeitada (nunca muda silenciosamente).
   */
  ajustar_quantidade_para_moq?: boolean
  /**
   * Concorrência otimista da MARGEM NEGOCIADA: valor `margem_versao` persistido
   * em cotacoes_itens no momento da leitura. Obrigatório (inteiro >= 1).
   * Divergência da persistida → 409 conflito_margem.
   *
   * NOTA: a margem em si NUNCA vem no payload — o servidor usa EXCLUSIVAMENTE a
   * margem persistida em cotacoes_itens.margem_negociada (fluxo de edição
   * autorizada acima; qualquer `margem`/valor enviado pelo cliente é REJEITADO).
   */
  margem_versao_esperada: number
}

// ---------- recibo ----------

export interface ReciboRodada {
  id: string
  numero_rodada: number
  tipo: 'selecao'
  estado: 'confirmada'
}

export interface ConfirmarCompraRecibo {
  ok: true
  cotacao_iten_id: string
  potencial_iten_id: string
  item_id: string
  potencial_id: string
  fornecedor_id: string
  /** Preço de compra confirmado (= preco_ofertado da oferta). */
  preco_compra: number
  /** Venda gravada em potencial_itens.preco_unitario (margem vigente, precisão do item). */
  preco_unitario: number
  /** Margem negociada PERSISTIDA em cotacoes_itens.margem_negociada usada no cálculo. */
  margem: number
  /** margem_versao APÓS o consumo (+1 incrementado dentro da transação). */
  margem_versao: MargemVersao
  /** Precisão (2 ou 3 casas) usada no arredondamento da venda. */
  precisao: 2 | 3
  moeda: string
  unidade: string
  quantidade: number
  moq: number
  /** true quando a quantidade foi ajustada ao MOQ explicitamente. */
  quantidade_ajustada_para_moq: boolean
  /** preco_original da oferta, preservado. */
  preco_original_preservado: number
  rodada: ReciboRodada
  autor: string
  data_confirmacao: string
}

export interface ConfirmarCompraResponse {
  /** true quando a resposta vem da chave de idempotência (retry, sem nova execução). */
  repetido: boolean
  recibo: ConfirmarCompraRecibo
}

// ---------- erros ----------

/** Códigos de erro estáveis retornados pelo endpoint em { error }. */
export type ConfirmarCompraErrorCode =
  | 'payload_invalido'
  | 'preco_invalido'
  | 'moq_invalido'
  | 'preco_eh_alvo'
  | 'oferta_vencida'
  | 'relacoes_incoerentes'
  | 'potencial_item_ambiguo'
  | 'quantidade_invalida'
  | 'quantidade_abaixo_moq'
  | 'moeda_ausente'
  | 'unidade_ausente'
  | 'venda_invalida'
  | 'pendencia_margem'
  | 'oferta_nao_encontrada'
  | 'cotacao_fornecedor_nao_encontrada'
  | 'potencial_nao_encontrado'
  | 'fornecedor_nao_encontrado'
  | 'item_nao_encontrado'
  | 'potencial_item_nao_encontrado'
  | 'conflito_versao'
  | 'conflito_idempotencia'
  | 'falha_transacao'
  | 'nao_autenticado'
  | 'acesso_negado'
  | 'identidade_nao_resolvida'
  | 'pendencia_dados'
  | 'precisao_ausente'
  | 'precisao_invalida'
  | 'margem_invalida'
  | 'conflito_margem'

/** Erro tipado do endpoint (código estável + mensagem em português). */
export class ConfirmarCompraError extends Error {
  readonly status: number
  readonly code: ConfirmarCompraErrorCode | string

  constructor(status: number, code: ConfirmarCompraErrorCode | string, message: string) {
    super(message)
    this.name = 'ConfirmarCompraError'
    this.status = status
    this.code = code
  }
}

/** Mapeia falha HTTP/SDK em ConfirmarCompraError com código estável. */
export function toConfirmarCompraError(err: unknown): ConfirmarCompraError {
  if (err instanceof ConfirmarCompraError) return err
  if (err instanceof ClientResponseError) {
    const data = (err.response ?? {}) as { error?: string; message?: string }
    return new ConfirmarCompraError(
      err.status,
      data.error ?? 'falha_transacao',
      data.message ?? err.message,
    )
  }
  return new ConfirmarCompraError(
    0,
    'falha_transacao',
    err instanceof Error ? err.message : 'Falha desconhecida na confirmação de compra.',
  )
}

// ---------- função cliente ----------

/**
 * Confirma a compra de um item de cotação (UMA transação server-side).
 * Não ligada a nenhuma UI nesta rodada — o frontend continua nos caminhos atuais.
 *
 * Lança ConfirmarCompraError com `code` estável em falha.
 */
export async function confirmarCompra(
  payload: ConfirmarCompraPayload,
): Promise<ConfirmarCompraResponse> {
  if (!payload.cotacao_iten_id) {
    throw new ConfirmarCompraError(400, 'payload_invalido', 'cotacao_iten_id é obrigatório.')
  }
  if (!payload.idempotency_key) {
    throw new ConfirmarCompraError(400, 'payload_invalido', 'idempotency_key é obrigatória.')
  }
  if (!payload.versao) {
    throw new ConfirmarCompraError(400, 'payload_invalido', 'versao é obrigatória.')
  }
  if (
    typeof payload.margem_versao_esperada !== 'number' ||
    !Number.isFinite(payload.margem_versao_esperada) ||
    payload.margem_versao_esperada < 1 ||
    payload.margem_versao_esperada !== Math.floor(payload.margem_versao_esperada)
  ) {
    throw new ConfirmarCompraError(
      400,
      'payload_invalido',
      'margem_versao_esperada é obrigatória (número inteiro >= 1).',
    )
  }

  if (!payload.potencial_iten_id || !payload.rodada_resposta_id || !payload.versoes_esperadas) {
    throw new ConfirmarCompraError(400, 'payload_invalido', 'Item, resposta e versões são obrigatórios.')
  }
  try {
    return await pb.send<ConfirmarCompraResponse>('/backend/v1/cotacoes/confirmar-compra', {
      method: 'POST',
      body: payload,
    })
  } catch (err) {
    throw toConfirmarCompraError(err)
  }
}

/**
 * Gera a chave de idempotência a partir da leitura da oferta: determinística
 * para o mesmo (oferta, versão) — um retry com payload idêntico reutiliza a mesma
 * chave; mudou a versão (oferta atualizada), nova chave é gerada.
 */
export function gerarIdempotencyKey(
  cotacaoItenId: string,
  versao: string,
  potencialItenId?: string,
): string {
  return ['confirmar-compra', cotacaoItenId, potencialItenId ?? '-', versao].join(':').replace(/[^A-Za-z0-9:_-]/g, '_').slice(0, 120)
}

export interface SalvarMargemPayload {
  cotacao_iten_id: string
  versao: string
  margem_versao_esperada: number
  margem_negociada: number
  precisao_negociada: 2 | 3
}
/** Candidate endpoint is still blocked with 503; used by the candidate review UI. */
export async function salvarMargemNegociada(payload: SalvarMargemPayload) {
  return pb.send<SalvarMargemPayload & { margem_versao: number }>(
    '/backend/v1/cotacoes/salvar-margem', { method: 'POST', body: payload },
  )
}

import pb from '../lib/pocketbase/client'
import {
